d.status AS "f_latestStatus",
d.log AS "f_latestLog",
CASE WHEN (CASE WHEN u.is_fr=1 OR c.is_friend IS TRUE THEN true WHEN (u.zalo_uid IS NOT NULL AND COALESCE(u.is_fr,0)=0) OR c.is_friend IS FALSE THEN false END) THEN 'Bạn bè' WHEN NOT (CASE WHEN u.is_fr=1 OR c.is_friend IS TRUE THEN true WHEN (u.zalo_uid IS NOT NULL AND COALESCE(u.is_fr,0)=0) OR c.is_friend IS FALSE THEN false END) THEN 'Chưa kết bạn' END AS "f_recipientStatus",
private.column_filter_zalo_tags_v1(c.extra_data) AS "f_zaloTags",
c.akabiz_tag_ids::text[] AS "f_akaBizTags"
 FROM rollup r JOIN public.auto_campaign_details d ON d.id=r.latest_id JOIN public.auto_campaigns campaign ON campaign.id=d.campaign_id
 LEFT JOIN public.auto_campaign_actions action ON action.id=campaign.action_id
 LEFT JOIN public.auto_account_contacts c ON c.account_id=campaign.account_id AND c.staff_id=$1 AND c.organization_id=$2 AND c.uid=r.uid AND c.contact_type='person' AND NOT c.is_delete
 LEFT JOIN public.zalo_users u ON u.account_id=campaign.account_id AND u.staff_id=$1 AND u.organization_id=$2 AND u.zalo_uid=r.uid
 LEFT JOIN LATERAL (SELECT m.zalo_group_id FROM public.zalo_group_members m WHERE m.account_id=campaign.account_id AND m.staff_id=$1 AND m.organization_id=$2 AND m.zalo_uid=r.uid ORDER BY m.is_current DESC,m.last_seen_at DESC,m.updated_at DESC,m.id DESC LIMIT 1) member ON nullif(btrim(COALESCE(c.extra_data->>'zaloGroupId',c.extra_data->>'zalo_group_id')),'') IS NULL
 LEFT JOIN public.zalo_groups g ON g.account_id=campaign.account_id AND g.staff_id=$1 AND g.organization_id=$2 AND g.zalo_group_id=COALESCE(NULLIF(btrim(c.extra_data->>'zaloGroupId'),''),NULLIF(btrim(c.extra_data->>'zalo_group_id'),''),NULLIF(btrim(member.zalo_group_id),''))
), filtered AS NOT MATERIALIZED (SELECT * FROM candidate WHERE %1$s
 AND (NOT ($3 ? 'ids') OR id IN (SELECT jsonb_array_elements_text($3->'ids')::bigint))
 AND (NOT ($3 ? 'excludeIds') OR id NOT IN (SELECT jsonb_array_elements_text($3->'excludeIds')::bigint))
 AND (NULLIF(btrim($3->>'search'),'') IS NULL OR strpos(lower(normalize(concat_ws(' ',f_name,f_uid,f_phone,extra_data->>'phoneNumber',extra_data->>'phone_number',extra_data->>'mobilePhone',extra_data->>'mobile_phone'),NFC)),lower(normalize(btrim($3->>'search'),NFC)))>0)
 AND ((COALESCE(jsonb_array_length($3->'zaloTagIds'),0)=0 AND NOT COALESCE(($3->>'zaloNoTag')::boolean,false)) OR "f_zaloTags" && ARRAY(SELECT jsonb_array_elements_text($3->'zaloTagIds')) OR (COALESCE(($3->>'zaloNoTag')::boolean,false) AND cardinality("f_zaloTags")=0))
 AND ((COALESCE(jsonb_array_length($3->'akaBizTagIds'),0)=0 AND NOT COALESCE(($3->>'akaBizNoTag')::boolean,false)) OR COALESCE(akabiz_tag_ids,'{}'::bigint[]) && ARRAY(SELECT jsonb_array_elements_text($3->'akaBizTagIds')::bigint) OR (COALESCE(($3->>'akaBizNoTag')::boolean,false) AND COALESCE(cardinality(akabiz_tag_ids),0)=0))
 ), matched AS %4$s (SELECT id,created_at FROM filtered),
 page AS MATERIALIZED (SELECT * FROM matched WHERE %2$s ORDER BY created_at DESC,id DESC OFFSET $5 LIMIT $6)
 SELECT jsonb_build_object('version',1,'total',%3$s,'rows',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,'account_id',c.account_id,'contact_type','person','name',c.f_name,'uid',c.f_uid,'url','','is_delete',false,'is_friend',c.is_friend,'akabiz_tag_ids',c.akabiz_tag_ids,
 'extra_data',c.extra_data||jsonb_build_object('phone',c.f_phone,'groupName',c."f_groupName",'sentCount',c."f_sentCount",'latestSentAt',c."f_latestSentAt",'latestSentDate',to_char(c."f_latestSentAt" AT TIME ZONE 'Asia/Ho_Chi_Minh','DD/MM/YYYY'),'daysSinceLatest',c."f_daysSinceLatest",'latestStatus',c."f_latestStatus",'latestLog',c."f_latestLog",'recipientStatus',c."f_recipientStatus")) ORDER BY p.created_at DESC,p.id DESC) FROM page p JOIN filtered c ON c.id=p.id),'[]'::jsonb),
 'after',(SELECT jsonb_build_object('createdAt',created_at,'id',id::text) FROM page ORDER BY created_at,id LIMIT 1),'hasMore',(SELECT count(*) FROM page)=$6)
 $query$;
 sql:=format(sql,predicate,cursor_clause,count_sql,CASE WHEN p_query->>'countMode'='none' THEN 'NOT MATERIALIZED' ELSE 'MATERIALIZED' END);
 EXECUTE sql INTO result USING p_staff_id,p_organization_id,p_query,actions,page_offset,page_limit;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_read_report_page(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_source text := p_query->>'source';
  v_view text := p_query->>'view';
  v_accounts bigint[];
  v_campaigns bigint[];
  v_actions text[];
  v_from timestamptz := (p_query->>'startIso')::timestamptz;
  v_to timestamptz := (p_query->>'endIso')::timestamptz;
  v_limit integer := coalesce((p_query->>'limit')::integer,1000);
  v_offset integer := coalesce((p_query->>'offset')::integer,0);
  v_count boolean := coalesce((p_query->>'count')::boolean,false);
  v_head boolean := coalesce((p_query->>'head')::boolean,false);
  v_filter jsonb := p_query->'filter';
  v_where text;
  v_table text;
  v_select text;
  v_order text;
  v_rows jsonb := '[]';
  v_total bigint;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  IF p_staff_id IS NULL OR p_organization_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.org_staff WHERE id=p_staff_id AND organization_id=p_organization_id AND is_active=true
  ) THEN RAISE EXCEPTION 'report_access_denied' USING ERRCODE='42501'; END IF;
  IF v_source IS NULL OR v_source NOT IN ('results','pending') OR v_view IS NULL OR v_view NOT IN ('summary','details')
    OR v_from IS NULL OR v_to IS NULL OR v_from>=v_to OR v_limit<0 OR v_limit>1000 OR v_offset<0
    OR jsonb_typeof(p_query->'accountIds') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_query->'accountIds')>10000
    OR (p_query ? 'campaignIds' AND (jsonb_typeof(p_query->'campaignIds') IS DISTINCT FROM 'array'
      OR jsonb_array_length(p_query->'campaignIds')>200)) THEN
    RAISE EXCEPTION 'invalid_report_query' USING ERRCODE='22023';
  END IF;
  SELECT coalesce(array_agg(value::bigint),'{}') INTO v_accounts FROM jsonb_array_elements_text(p_query->'accountIds');
  SELECT array_agg(value::bigint) INTO v_campaigns FROM jsonb_array_elements_text(p_query->'campaignIds');
  SELECT coalesce(array_agg(value),'{}') INTO v_actions FROM jsonb_array_elements_text(p_query->'actionCodes');
  IF EXISTS (SELECT 1 FROM unnest(v_accounts) requested(id) WHERE NOT EXISTS (
    SELECT 1 FROM public.auto_accounts a WHERE a.id=requested.id AND a.staff_id=p_staff_id
      AND a.organization_id=p_organization_id AND a.is_delete=false
  )) THEN RAISE EXCEPTION 'report_account_access_denied' USING ERRCODE='42501'; END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_campaigns) requested(id) WHERE NOT EXISTS (
    SELECT 1 FROM public.auto_campaigns c WHERE c.id=requested.id AND c.staff_id=p_staff_id AND c.organization_id=p_organization_id
  )) THEN RAISE EXCEPTION 'report_campaign_access_denied' USING ERRCODE='42501'; END IF;
  IF cardinality(v_accounts)=0 OR (p_query ? 'campaignIds' AND v_campaigns IS NULL) THEN
    RETURN jsonb_build_object('rows','[]'::jsonb,'count',CASE WHEN v_count OR v_head THEN 0 ELSE NULL END);
  END IF;

  -- All dynamic fragments below are fixed SQL; every caller value stays a bound parameter.
  IF v_source='results' THEN
    v_table := 'public.auto_campaign_details d';
    v_where := 'd.is_delete=false AND d.account_id=ANY($3) AND d.action_code=ANY($5) AND d.created_at >= $6 AND d.created_at < $7';
    IF v_campaigns IS NOT NULL THEN v_where:=v_where||' AND d.campaign_id=ANY($4)'; END IF;
    IF coalesce((p_query->>'requireCampaign')::boolean,false) THEN
      v_where:=v_where||' AND EXISTS (SELECT 1 FROM public.auto_campaigns c WHERE c.id=d.campaign_id AND c.staff_id=$1 AND c.organization_id=$2)';
    END IF;
    IF v_filter->>'kind'='group' THEN
      IF v_filter->>'group' IS NULL OR v_filter->>'group' NOT IN ('all','success','failure','skipped','pending') THEN
        RAISE EXCEPTION 'invalid_report_group' USING ERRCODE='22023';
      END IF;
      v_where:=v_where||' AND ((($8#>>''{filter,group}'')=''all'' AND d.report_group IN (''success'',''failure'',''skipped'',''pending''))
        OR d.report_group=($8#>>''{filter,group}'') OR (d.report_group IS NULL AND d.status IN
          (SELECT jsonb_array_elements_text($8#>''{filter,legacyStatuses}''))))';
    ELSIF v_filter->>'kind' IN ('status','legacy') THEN
      v_where:=v_where||' AND d.report_group IS DISTINCT FROM ''pending''';
      IF v_filter->>'kind'='status' THEN
        IF (v_filter->>'statusId')::bigint IS NULL OR (v_filter->>'statusId')::bigint<=0 THEN
          RAISE EXCEPTION 'invalid_report_status' USING ERRCODE='22023';
        END IF;
        v_where:=v_where||' AND (d.status_id=($8#>>''{filter,statusId}'')::bigint OR (d.status_id IS NULL
          AND d.status=($8#>>''{filter,legacyStatus}'')))';
      ELSE
        IF jsonb_typeof(v_filter->'status') IS DISTINCT FROM 'string' THEN
          RAISE EXCEPTION 'invalid_report_legacy_status' USING ERRCODE='22023';
        END IF;
        v_where:=v_where||' AND d.status_id IS NULL AND d.status=($8#>>''{filter,status}'')';
      END IF;
    ELSIF v_filter IS NOT NULL AND v_filter<>'null'::jsonb THEN
      RAISE EXCEPTION 'invalid_report_filter' USING ERRCODE='22023';
    END IF;
    v_order:=CASE WHEN v_view='summary' THEN 'd.created_at ASC,d.id ASC' ELSE 'd.created_at DESC,d.id DESC' END;
    IF p_query ? 'afterCreatedAt' THEN
      IF p_query->>'afterId' IS NULL THEN RAISE EXCEPTION 'invalid_report_cursor'; END IF;
      v_where:=v_where||' AND (d.created_at,d.id)'||CASE WHEN v_view='summary' THEN '>' ELSE '<' END
        ||'(($8->>''afterCreatedAt'')::timestamptz,($8->>''afterId'')::bigint)';
    END IF;
    IF v_view='summary' THEN
      v_select:='d.id,d.input_data_id,d.account_id,d.action_code,d.status,d.status_id,d.report_group,d.created_at';
    ELSE
      v_select:='d.id,d.input_data_id,d.campaign_id,d.account_id,d.action_code,d.action_name,d.status,d.error_code,d.log,d.data,d.post_url,d.created_at,
        (SELECT jsonb_build_object(''name'',s.name) FROM public.auto_status s WHERE s.id=d.status_id) AS main_status,
        (SELECT jsonb_build_object(''name'',s.name) FROM public.auto_status s WHERE s.id=d.sub_status_id) AS sub_status,
        (SELECT jsonb_build_object(''id'',c.id,''name'',c.name,''staff_id'',c.staff_id,''organization_id'',c.organization_id)
          FROM public.auto_campaigns c WHERE c.id=d.campaign_id AND c.staff_id=$1 AND c.organization_id=$2) AS auto_campaigns,
        (SELECT jsonb_build_object(''name'',i.name,''uid'',i.uid,''phone'',i.phone,''email'',i.email)
          FROM public.auto_campaign_input_data i JOIN public.auto_campaigns c ON c.id=i.campaign_id
          WHERE i.id=d.input_data_id AND c.staff_id=$1 AND c.organization_id=$2) AS report_input';
    END IF;
  ELSE
    IF v_campaigns IS NULL THEN RAISE EXCEPTION 'report_campaign_scope_required' USING ERRCODE='22023'; END IF;
    v_table:='public.auto_campaign_input_data d JOIN public.auto_campaigns c ON c.id=d.campaign_id';
    v_where:='d.campaign_id=ANY($4) AND d.is_delete=false AND d.status=''chờ xử lý'' AND c.is_delete=false
      AND c.staff_id=$1 AND c.organization_id=$2 AND c.account_id=ANY($3)';
    IF v_view='summary' THEN
      IF p_query->>'ownSchedule' IS NULL THEN RAISE EXCEPTION 'report_schedule_branch_required'; END IF;
      v_where:=v_where||CASE WHEN (p_query->>'ownSchedule')::boolean
        THEN ' AND d.schedule >= $6 AND d.schedule < $7'
        ELSE ' AND d.schedule IS NULL AND c.schedule >= $6 AND c.schedule < $7' END;
      v_select:='d.id,d.campaign_id,d.schedule';
    ELSE
      v_where:=v_where||' AND ((d.schedule >= $6 AND d.schedule < $7) OR (d.schedule IS NULL AND c.schedule >= $6 AND c.schedule < $7))';
      IF cardinality(v_accounts)<>1 OR cardinality(v_actions)<>1 THEN RAISE EXCEPTION 'report_pending_cell_required'; END IF;
      v_where:=v_where||' AND NOT EXISTS (SELECT 1 FROM public.auto_campaign_details r WHERE r.input_data_id=d.id
        AND r.account_id=ANY($3) AND r.action_code=ANY($5) AND r.is_delete=false AND r.report_group=''pending''
        AND r.created_at >= $6 AND r.created_at < $7)';
      v_select:='d.id,d.campaign_id,d.name,d.phone,d.uid,d.email,d.note,d.schedule,d.created_at';
    END IF;
    v_order:='d.campaign_id ASC,d.id ASC';
    IF p_query ? 'afterId' THEN
      IF p_query->>'afterCampaignId' IS NULL THEN RAISE EXCEPTION 'invalid_report_pending_cursor'; END IF;
      v_where:=v_where||' AND (d.campaign_id,d.id)>(($8->>''afterCampaignId'')::bigint,($8->>''afterId'')::bigint)';
    END IF;
  END IF;
  IF v_count OR v_head THEN
    EXECUTE 'SELECT count(*) FROM '||v_table||' WHERE '||v_where INTO v_total
      USING p_staff_id,p_organization_id,v_accounts,v_campaigns,v_actions,v_from,v_to,p_query;
  END IF;
  IF NOT v_head AND v_limit>0 THEN
    EXECUTE 'SELECT coalesce(jsonb_agg(to_jsonb(r)),''[]''::jsonb) FROM (SELECT '||v_select||' FROM '||v_table
      ||' WHERE '||v_where||' ORDER BY '||v_order||' LIMIT $9 OFFSET $10) r' INTO v_rows
      USING p_staff_id,p_organization_id,v_accounts,v_campaigns,v_actions,v_from,v_to,p_query,v_limit,v_offset;
  END IF;
  RETURN jsonb_build_object('rows',v_rows,'count',v_total);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_recover_campaign_runtime_unit_leases(p_staff_id bigint, p_runtime_target text, p_platform_scope text DEFAULT 'all'::text)
 RETURNS TABLE(ok boolean, reason text, recovered_lease_count bigint, requeued_input_count bigint, db_now timestamp with time zone, vietnam_date_key date)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_random record;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_platform_scope text := lower(btrim(COALESCE(p_platform_scope, '')));
  v_organization_id bigint;
  v_candidate record;
  v_locked_token uuid;
  v_locked_input_data_ids bigint[];
  v_recovered_lease_count bigint := 0;
  v_requeued_input_count bigint := 0;
  v_row_count bigint := 0;
  v_now timestamptz := clock_timestamp();
  v_vietnam_date date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'staff ID must be a positive integer';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'runtime target must be desktop or server';
  END IF;
  IF v_platform_scope NOT IN ('all', 'zalo') THEN
    RAISE EXCEPTION 'platform scope must be all or zalo';
  END IF;

  -- Startup recovery is cleanup and therefore remains available for an
  -- inactive staff row. The caller must invoke it only after its existing
  -- runtime-specific recovery has proved the scheduler process idle.
  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
  FOR SHARE OF staff;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', 0::bigint, 0::bigint,
      v_now, v_vietnam_date;
    RETURN;
  END IF;

  FOR v_candidate IN
    SELECT campaign.id AS campaign_id,
      campaign.account_id,
      campaign.runtime_unit_token,
      campaign.runtime_unit_input_data_ids
    FROM public.auto_campaigns AS campaign
    JOIN public.auto_accounts AS account
      ON account.id = campaign.account_id
     AND account.staff_id = campaign.staff_id
    WHERE campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token IS NOT NULL
      AND (
        v_platform_scope = 'all'
        OR lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      )
      AND (
        campaign.organization_id IS NULL
        OR campaign.organization_id = v_organization_id
      )
      AND (
        account.organization_id IS NULL
        OR account.organization_id = v_organization_id
      )
      AND (
        (
          v_runtime_target = 'server'
          AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
          AND COALESCE(account.is_zalo_show_web, false) = false
          AND COALESCE(account.is_zalo_server, false) = true
        )
        OR (
          v_runtime_target = 'desktop'
          AND NOT (
            lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
            AND COALESCE(account.is_zalo_server, false) = true
          )
        )
      )
    ORDER BY campaign.id
  LOOP
    PERFORM public.aka_agent_lock_campaign_input_serialization(
      v_candidate.campaign_id
    );

    IF cardinality(COALESCE(
      v_candidate.runtime_unit_input_data_ids,
      ARRAY[]::bigint[]
    )) > 0 THEN
      PERFORM input_data.id
      FROM public.auto_campaign_input_data AS input_data
      WHERE input_data.id = ANY(v_candidate.runtime_unit_input_data_ids)
        AND input_data.campaign_id = v_candidate.campaign_id
      ORDER BY input_data.id
      FOR UPDATE OF input_data;
    END IF;

    SELECT campaign.runtime_unit_token,
      campaign.runtime_unit_input_data_ids
    INTO v_locked_token, v_locked_input_data_ids
    FROM public.auto_campaigns AS campaign
    JOIN public.auto_accounts AS account
      ON account.id = campaign.account_id
     AND account.staff_id = campaign.staff_id
    WHERE campaign.id = v_candidate.campaign_id
      AND campaign.account_id = v_candidate.account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token = v_candidate.runtime_unit_token
      AND (
        v_platform_scope = 'all'
        OR lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      )
      AND (
        campaign.organization_id IS NULL
        OR campaign.organization_id = v_organization_id
      )
      AND (
        account.organization_id IS NULL
        OR account.organization_id = v_organization_id
      )
      AND (
        (
          v_runtime_target = 'server'
          AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
          AND COALESCE(account.is_zalo_show_web, false) = false
          AND COALESCE(account.is_zalo_server, false) = true
        )
        OR (
          v_runtime_target = 'desktop'
          AND NOT (
            lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
            AND COALESCE(account.is_zalo_server, false) = true
          )
        )
      )
    FOR UPDATE OF campaign, account;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    PERFORM private.facebook_random_unit_recover(v_candidate.campaign_id,v_candidate.account_id,v_locked_token);

    IF cardinality(COALESCE(v_locked_input_data_ids, ARRAY[]::bigint[])) > 0 THEN
      UPDATE public.auto_campaign_input_data AS input_data
      SET status = 'chờ xử lý', date_action = NULL
      WHERE input_data.id = ANY(v_locked_input_data_ids)
        AND input_data.campaign_id = v_candidate.campaign_id
        AND input_data.status = 'đang chạy';
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      v_requeued_input_count := v_requeued_input_count + v_row_count;
    END IF;

    v_now := clock_timestamp();
    UPDATE public.auto_campaigns AS campaign
    SET runtime_unit_token = NULL,
      runtime_unit_vietnam_date = NULL,
      runtime_unit_claimed_at = NULL,
      runtime_unit_input_data_ids = NULL,
      updated_at = v_now
    WHERE campaign.id = v_candidate.campaign_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token = v_locked_token;

    IF FOUND THEN
      v_recovered_lease_count := v_recovered_lease_count + 1;
    END IF;
  END LOOP;

  -- Same startup recovery proof/locks; includes orphan turns when mode is off.
  IF v_runtime_target='desktop' AND v_platform_scope='all' THEN
    FOR v_random IN SELECT * FROM private.facebook_random_orphan_turns(p_staff_id,v_organization_id) ORDER BY id
    LOOP
      PERFORM public.aka_agent_lock_campaign_input_serialization(v_random.id);
      PERFORM 1 FROM public.auto_campaigns cc JOIN public.auto_accounts aa ON aa.id=cc.account_id AND aa.staff_id=cc.staff_id
        WHERE cc.id=v_random.id AND cc.account_id=v_random.account_id AND cc.staff_id=p_staff_id AND aa.flatform_type='facebook'
          AND (cc.organization_id IS NULL OR cc.organization_id=v_organization_id)
          AND (aa.organization_id IS NULL OR aa.organization_id=v_organization_id)
          AND cc.runtime_claim_token IS NULL AND cc.runtime_unit_token IS NULL AND cc.status<>'đang chạy'
        FOR UPDATE OF cc,aa;
      IF FOUND THEN PERFORM private.facebook_random_finalize_turn(v_random.id,v_random.account_id,v_random.claim::uuid,v_random.unit::uuid,true); END IF;
    END LOOP;
  END IF;
  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  RETURN QUERY SELECT
    true, 'recovered', v_recovered_lease_count, v_requeued_input_count,
    v_now, v_vietnam_date;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_reset_device_binding(p_username text, p_password text, p_source text, p_request_id uuid, p_expected_binding jsonb, p_device jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  s public.org_staff%ROWTYPE;
  h public.auto_staff_device_change_history%ROWTYPE;
  remaining integer;
  remaining_after integer;
  outcome text;
  stamp timestamptz;
  device jsonb;
BEGIN
  IF p_source IS NULL OR p_source NOT IN ('login', 'account_menu') OR p_request_id IS NULL
     OR jsonb_typeof(p_expected_binding) IS DISTINCT FROM 'object'
     OR NOT (p_expected_binding ?& ARRAY['staffId','hash','boundAt'])
     OR jsonb_typeof(p_device) IS DISTINCT FROM 'object'
     OR coalesce(p_device->>'fingerprintHash','') !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid device change request' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username) FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'changed',false,'code','not_found','remainingChanges',null); END IF;
  remaining := coalesce(s.device_changes_remaining, 5);
  IF NOT s.is_active THEN outcome := 'inactive';
  ELSIF p_source = 'account_menu' AND s.password IS DISTINCT FROM p_password THEN outcome := 'not_authorized';
  ELSIF s.id::text IS DISTINCT FROM p_expected_binding->>'staffId' THEN outcome := 'binding_conflict';
  END IF;
  IF outcome IS NOT NULL THEN
    RETURN jsonb_build_object('success',false,'changed',false,'code',outcome,'remainingChanges',remaining);
  END IF;

  -- Whitelist metadata: the history must never persist arbitrary credentials.
  device := jsonb_build_object('fingerprintHash',p_device->>'fingerprintHash',
    'label',left(p_device->>'label',255),'platform',left(p_device->>'platform',20),
    'appVersion',left(p_device->>'appVersion',50));
  SELECT * INTO h FROM public.auto_staff_device_change_history WHERE request_id = p_request_id;
  IF FOUND THEN
    IF h.staff_id <> s.id OR h.source <> p_source
       OR h.requesting_device->>'fingerprintHash' IS DISTINCT FROM device->>'fingerprintHash'
       OR h.old_binding->>'hash' IS DISTINCT FROM p_expected_binding->>'hash'
       OR (h.old_binding->>'boundAt')::timestamptz IS DISTINCT FROM (p_expected_binding->>'boundAt')::timestamptz THEN
      RETURN jsonb_build_object('success',false,'changed',false,'code','binding_conflict','remainingChanges',remaining);
    END IF;
    RETURN jsonb_build_object('success',true,'changed',true,'code','changed','remainingChanges',h.remaining_after);
  END IF;

  IF s.device_fingerprint_hash IS NULL THEN outcome := 'already_unbound';
  ELSIF p_source = 'account_menu' AND s.device_fingerprint_hash IS DISTINCT FROM device->>'fingerprintHash' THEN outcome := 'not_authorized';
  ELSIF s.device_fingerprint_hash IS DISTINCT FROM p_expected_binding->>'hash'
     OR s.device_bound_at IS DISTINCT FROM (p_expected_binding->>'boundAt')::timestamptz THEN outcome := 'binding_conflict';
  ELSIF p_source = 'login' AND remaining <= 0 THEN outcome := 'quota_exhausted';
  END IF;
  stamp := clock_timestamp();
  IF outcome IS NULL AND p_source = 'login' AND EXISTS (
    SELECT 1 FROM public.auto_staff_device_presence
    WHERE staff_id = s.id AND ended_at IS NULL AND last_seen_at > stamp - interval '120 seconds'
  ) THEN outcome := 'device_online'; END IF;
  IF outcome IS NOT NULL THEN
    RETURN jsonb_build_object('success',outcome = 'already_unbound','changed',false,'code',outcome,'remainingChanges',remaining);
  END IF;

  -- Only the unauthenticated login flow consumes the device-change quota.
  remaining_after := remaining - CASE WHEN p_source = 'login' THEN 1 ELSE 0 END;
  UPDATE public.org_staff SET device_fingerprint_hash = NULL, device_label = NULL,
    device_platform = NULL, device_bound_at = NULL, device_last_seen_at = NULL,
    device_changes_remaining = CASE WHEN p_source = 'login' THEN remaining_after ELSE s.device_changes_remaining END,
    updated_at = stamp
  WHERE id = s.id;
  UPDATE public.auto_staff_device_login_settings SET remember_login = false, auto_login = false, updated_at = stamp
  WHERE staff_id = s.id AND device_fingerprint_hash = s.device_fingerprint_hash;
  INSERT INTO public.auto_staff_device_change_history
    (request_id,staff_id,organization_id,source,old_binding,requesting_device,remaining_before,remaining_after,created_at)
  VALUES (p_request_id,s.id,s.organization_id,p_source,
    jsonb_build_object('hash',s.device_fingerprint_hash,'label',s.device_label,'platform',s.device_platform,'boundAt',s.device_bound_at),
    device,remaining,remaining_after,stamp);
  RETURN jsonb_build_object('success',true,'changed',true,'code','changed','remainingChanges',remaining_after);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_reset_device_binding_v2(p_username text, p_password text, p_source text, p_request_id uuid, p_expected_binding jsonb, p_device jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  s public.org_staff%ROWTYPE;
  h public.auto_staff_device_change_history%ROWTYPE;
  remaining integer;
  remaining_after integer;
  outcome text;
  stamp timestamptz;
  device jsonb;
  revision text;
BEGIN
  IF p_source IS NULL OR p_source NOT IN ('login', 'account_menu') OR p_request_id IS NULL
     OR jsonb_typeof(p_expected_binding) IS DISTINCT FROM 'object'
     OR NOT (p_expected_binding ?& ARRAY['staffId','hash','revision','version'])
     OR p_expected_binding->>'version' IS DISTINCT FROM '2'
     OR coalesce(p_expected_binding->>'revision','') !~ '^[0-9]+$'
     OR jsonb_typeof(p_device) IS DISTINCT FROM 'object'
     OR coalesce(p_device->>'fingerprintHash','') !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid device change request' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username) FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'changed',false,'code','not_found','remainingChanges',null); END IF;
  SELECT xmin::text INTO revision FROM public.org_staff WHERE id=s.id;
  remaining := coalesce(s.device_changes_remaining, 5);
  IF NOT s.is_active THEN outcome := 'inactive';
  ELSIF p_source = 'account_menu' AND s.password IS DISTINCT FROM p_password THEN outcome := 'not_authorized';
  ELSIF s.id::text IS DISTINCT FROM p_expected_binding->>'staffId' THEN outcome := 'binding_conflict';
  END IF;
  IF outcome IS NOT NULL THEN
    RETURN jsonb_build_object('success',false,'changed',false,'code',outcome,'remainingChanges',remaining);
  END IF;

  -- Whitelist metadata: the history must never persist arbitrary credentials.
  device := jsonb_build_object('fingerprintHash',p_device->>'fingerprintHash',
    'label',left(p_device->>'label',255),'platform',left(p_device->>'platform',20),
    'appVersion',left(p_device->>'appVersion',50),'bindingVersion',2);
  SELECT * INTO h FROM public.auto_staff_device_change_history WHERE request_id = p_request_id;
  IF FOUND THEN
    IF h.staff_id <> s.id OR h.source <> p_source
       OR h.requesting_device->>'fingerprintHash' IS DISTINCT FROM device->>'fingerprintHash'
       OR h.old_binding->>'hash' IS DISTINCT FROM p_expected_binding->>'hash'
       OR h.old_binding->>'version' IS DISTINCT FROM '2'
       OR h.old_binding->>'revision' IS DISTINCT FROM p_expected_binding->>'revision' THEN
      RETURN jsonb_build_object('success',false,'changed',false,'code','binding_conflict','remainingChanges',remaining);
    END IF;
    RETURN jsonb_build_object('success',true,'changed',true,'code','changed','remainingChanges',h.remaining_after);
  END IF;

  IF s.aka_agent_device_fingerprint_hash IS NULL THEN outcome := 'already_unbound';
  ELSIF p_source = 'account_menu' AND s.aka_agent_device_fingerprint_hash IS DISTINCT FROM device->>'fingerprintHash' THEN outcome := 'not_authorized';
  ELSIF s.aka_agent_device_fingerprint_hash IS DISTINCT FROM p_expected_binding->>'hash'
     OR revision IS DISTINCT FROM p_expected_binding->>'revision' THEN outcome := 'binding_conflict';
  ELSIF p_source = 'login' AND remaining <= 0 THEN outcome := 'quota_exhausted';
  END IF;
  stamp := clock_timestamp();
  IF outcome IS NULL AND p_source = 'login' AND EXISTS (
    SELECT 1 FROM public.auto_staff_device_presence
    WHERE staff_id = s.id AND ended_at IS NULL AND last_seen_at > stamp - interval '120 seconds'
  ) THEN outcome := 'device_online'; END IF;
  IF outcome IS NOT NULL THEN
    RETURN jsonb_build_object('success',outcome = 'already_unbound','changed',false,'code',outcome,'remainingChanges',remaining);
  END IF;

  -- Only the unauthenticated login flow consumes the device-change quota.
  remaining_after := remaining - CASE WHEN p_source = 'login' THEN 1 ELSE 0 END;
  UPDATE public.org_staff SET aka_agent_device_fingerprint_hash = NULL,
    device_changes_remaining = CASE WHEN p_source = 'login' THEN remaining_after ELSE s.device_changes_remaining END,
    updated_at = stamp
  WHERE id = s.id;
  INSERT INTO public.auto_staff_device_change_history
    (request_id,staff_id,organization_id,source,old_binding,requesting_device,remaining_before,remaining_after,created_at)
  VALUES (p_request_id,s.id,s.organization_id,p_source,
    jsonb_build_object('hash',s.aka_agent_device_fingerprint_hash,'revision',revision,'version',2),
    device,remaining,remaining_after,stamp);
  RETURN jsonb_build_object('success',true,'changed',true,'code','changed','remainingChanges',remaining_after);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_desktop_campaign_status_v2(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_target_status text)
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, db_now timestamp with time zone, vietnam_date_key date)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_target_status text := btrim(COALESCE(p_target_status, ''));
  v_organization_id bigint;
  v_campaign_found boolean := false;
  v_campaign_status text;
  v_account_status text;
  v_campaign_is_delete boolean;
  v_account_is_delete boolean;
  v_account_is_active boolean;
  v_account_platform text;
  v_account_is_zalo_server boolean;
  v_runtime_claim_token uuid;
  v_runtime_claim_target text;
  v_runtime_unit_token uuid;
  v_now timestamptz := clock_timestamp();
  v_vietnam_date date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  v_reason text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'campaign, account and staff IDs must be positive integers';
  END IF;
  IF v_target_status NOT IN ('tạm dừng', 'chờ xử lý') THEN
    RAISE EXCEPTION 'target status must be paused or pending';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true
  FOR SHARE OF staff;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', NULL::text, NULL::text,
      v_now, v_vietnam_date;
    RETURN;
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  SELECT campaign.status, account.status,
    COALESCE(campaign.is_delete, false),
    COALESCE(account.is_delete, false),
    COALESCE(account.is_active, false),
    lower(btrim(COALESCE(account.flatform_type, ''))),
    COALESCE(account.is_zalo_server, false),
    campaign.runtime_claim_token,
    campaign.runtime_claim_target,
    campaign.runtime_unit_token
  INTO v_campaign_status, v_account_status,
    v_campaign_is_delete, v_account_is_delete, v_account_is_active,
    v_account_platform, v_account_is_zalo_server,
    v_runtime_claim_token, v_runtime_claim_target, v_runtime_unit_token
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF campaign, account;
  v_campaign_found := FOUND;

  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  IF NOT v_campaign_found THEN
    RETURN QUERY SELECT
      false, 'not_found', NULL::text, NULL::text,
      v_now, v_vietnam_date;
    RETURN;
  END IF;

  IF v_account_platform = 'zalo' AND v_account_is_zalo_server THEN
    v_reason := 'runtime_not_owner';
  ELSIF v_campaign_is_delete THEN
    v_reason := 'campaign_deleted';
  ELSIF v_account_is_delete AND v_target_status <> 'tạm dừng' THEN
    v_reason := 'account_deleted';
  ELSIF NOT v_account_is_active AND v_target_status <> 'tạm dừng' THEN
    v_reason := 'account_inactive';
  ELSIF v_target_status = 'tạm dừng' THEN
    IF v_campaign_status = 'tạm dừng' THEN
      v_reason := 'already_target';
    ELSIF (v_campaign_status = 'đang chạy' AND NOT v_account_is_delete)
      OR v_runtime_claim_token IS NOT NULL
    THEN
      v_reason := 'runtime_busy';
    ELSIF v_runtime_unit_token IS NOT NULL THEN
      v_reason := 'unit_lease_busy';
    ELSIF v_campaign_status IS DISTINCT FROM 'chờ xử lý'
      AND NOT (v_account_is_delete AND v_campaign_status = 'đang chạy') THEN
      v_reason := 'invalid_transition';
    ELSE
      UPDATE public.auto_campaigns AS campaign
      SET status = 'tạm dừng',
        note = CASE
          WHEN campaign.data_target_source_mode = 'data_group'
            AND campaign.note IN ('Chờ data phù hợp', 'Chờ data mới')
          THEN campaign.note
          ELSE NULL
        END,
        updated_at = v_now
      WHERE campaign.id = p_campaign_id
        AND campaign.account_id = p_account_id
        AND campaign.staff_id = p_staff_id
        AND (campaign.status = 'chờ xử lý'
          OR (v_account_is_delete AND campaign.status = 'đang chạy'))
        AND campaign.runtime_claim_token IS NULL
        AND campaign.runtime_unit_token IS NULL;
      IF FOUND THEN
        v_campaign_status := 'tạm dừng';
        v_reason := 'updated';
      ELSE
        v_reason := 'runtime_busy';
      END IF;
    END IF;
  ELSE
    IF v_campaign_status = 'đang chạy' THEN
      v_reason := 'runtime_busy';
    ELSIF v_runtime_unit_token IS NOT NULL THEN
      v_reason := 'unit_lease_busy';
    ELSIF v_runtime_claim_token IS NOT NULL
      AND v_runtime_claim_target IS DISTINCT FROM 'server'
    THEN
      v_reason := 'runtime_busy';
    ELSIF NOT v_account_is_active THEN
      v_reason := 'account_inactive';
    ELSIF v_campaign_status IS DISTINCT FROM 'tạm dừng' THEN
      v_reason := 'invalid_transition';
    ELSE
      UPDATE public.auto_campaigns AS campaign
      SET status = 'chờ xử lý', note = NULL, updated_at = v_now
      WHERE campaign.id = p_campaign_id
        AND campaign.account_id = p_account_id
        AND campaign.staff_id = p_staff_id
        AND campaign.status = 'tạm dừng'
        AND (
          campaign.runtime_claim_token IS NULL
          OR campaign.runtime_claim_target = 'server'
        )
        AND campaign.runtime_unit_token IS NULL;
      IF FOUND THEN
        v_campaign_status := 'chờ xử lý';
        v_reason := 'updated';
      ELSE
        v_reason := 'runtime_busy';
      END IF;
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_reason IN ('updated', 'already_target'),
    v_reason,
    v_campaign_status,
    v_account_status,
    v_now,
    v_vietnam_date;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_zalo_server_account_status(p_account_id bigint, p_staff_id bigint, p_status text)
 RETURNS TABLE(ok boolean, reason text, account_id bigint, account_status text, campaign_status text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_status text := lower(btrim(COALESCE(p_status, '')));
  v_organization_id bigint;
  v_capabilities record;
  v_account_status text;
  v_campaign_status text;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_target_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RETURN QUERY SELECT false, 'invalid_transition', p_account_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_account_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR NOT COALESCE(v_capabilities.server_enabled, false)
  THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_account_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT account.status INTO v_account_status
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'not_found', p_account_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT campaign.status INTO v_campaign_status
  FROM public.auto_campaigns AS campaign
  WHERE campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = v_organization_id
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND COALESCE(campaign.is_delete, false) = false
    AND campaign.status IN ('đang chạy', 'tạm dừng', 'chờ xử lý')
  ORDER BY CASE campaign.status WHEN 'đang chạy' THEN 0 WHEN 'tạm dừng' THEN 1 ELSE 2 END,
    campaign.updated_at DESC NULLS LAST, campaign.id DESC
  LIMIT 1;

  IF v_account_status = v_target_status THEN
    RETURN QUERY SELECT true, 'already_target', p_account_id, v_account_status, v_campaign_status;
    RETURN;
  END IF;
  IF (v_target_status = 'tạm dừng' AND v_account_status IN ('chờ xử lý', 'đang chạy'))
    OR (v_target_status = 'chờ xử lý' AND v_account_status = 'tạm dừng')
  THEN
    UPDATE public.auto_accounts SET status = v_target_status, updated_at = now()
    WHERE id = p_account_id;
    RETURN QUERY SELECT true, 'updated', p_account_id, v_target_status, v_campaign_status;
    RETURN;
  END IF;
  RETURN QUERY SELECT false, 'invalid_transition', p_account_id, v_account_status, v_campaign_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_zalo_server_campaign_status(p_campaign_id bigint, p_staff_id bigint, p_status text)
 RETURNS TABLE(ok boolean, reason text, campaign_id bigint, campaign_status text, account_status text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_status text := lower(btrim(COALESCE(p_status, '')));
  v_organization_id bigint;
  v_capabilities record;
  v_campaign_status text;
  v_account_status text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Campaign and staff IDs must be positive integers';
  END IF;
  IF v_target_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RETURN QUERY SELECT false, 'invalid_transition', p_campaign_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_campaign_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR NOT COALESCE(v_capabilities.server_enabled, false)
  THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_campaign_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT campaign.status, account.status
  INTO v_campaign_status, v_account_status
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND (campaign.organization_id IS NULL OR campaign.organization_id = v_organization_id)
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND COALESCE(campaign.is_delete, false) = false
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
    AND (v_target_status = 'tạm dừng' OR COALESCE(account.is_delete, false) = false)
  FOR UPDATE OF campaign, account;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'not_found', p_campaign_id, NULL::text, NULL::text;
    RETURN;
  END IF;
  IF v_campaign_status = v_target_status THEN
    RETURN QUERY SELECT true, 'already_target', p_campaign_id, v_campaign_status, v_account_status;
    RETURN;
  END IF;
  IF (v_target_status = 'tạm dừng' AND v_campaign_status IN ('chờ xử lý', 'đang chạy'))
    OR (v_target_status = 'chờ xử lý' AND v_campaign_status = 'tạm dừng')
  THEN
    UPDATE public.auto_campaigns AS campaign
    SET
      status = v_target_status,
      note = CASE
        WHEN campaign.data_target_source_mode = 'data_group'
          AND btrim(COALESCE(campaign.note, '')) IN ('Chờ data phù hợp', 'Chờ data mới')
        THEN campaign.note
        ELSE NULL
      END,
      updated_at = now()
    WHERE campaign.id = p_campaign_id;
    RETURN QUERY SELECT true, 'updated', p_campaign_id, v_target_status, v_account_status;
    RETURN;
  END IF;
  RETURN QUERY SELECT false, 'invalid_transition', p_campaign_id, v_campaign_status, v_account_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_settle_action_results_v1(p_staff_id bigint, p_campaign_id bigint, p_account_id bigint, p_claim_token uuid, p_unit_token uuid, p_input_data_id bigint, p_detail_ids bigint[], p_input_patch jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
 c public.auto_campaigns%ROWTYPE;
 i public.auto_campaign_input_data%ROWTYPE;
 d public.auto_campaign_details%ROWTYPE;
 v_ids bigint[];
 v_bad text:='ignore'; v_effect text:='none'; v_committed boolean:=false; v_reset_before boolean:=false;
 v_existing jsonb; v_settlement jsonb; v_count integer; v_status text;
BEGIN
 IF p_claim_token IS NULL OR p_unit_token IS NULL OR (COALESCE(cardinality(p_detail_ids),0)=0 AND (p_input_patch->'suppressedResult' IS NULL))
   OR array_position(p_detail_ids,NULL) IS NOT NULL
   OR (p_input_patch IS NOT NULL AND jsonb_typeof(p_input_patch)<>'object')
 THEN RAISE EXCEPTION 'action_result_settlement_invalid'; END IF;
 PERFORM 1 FROM public.org_staff WHERE id=p_staff_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'action_result_scope_invalid'; END IF;
 PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);
 IF p_input_data_id IS NOT NULL THEN
   SELECT * INTO i FROM public.auto_campaign_input_data WHERE id=p_input_data_id AND campaign_id=p_campaign_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'action_result_input_invalid'; END IF;
 END IF;
 SELECT x.* INTO c FROM public.auto_campaigns x JOIN public.auto_accounts a ON a.id=p_account_id
   AND a.staff_id=x.staff_id AND a.organization_id IS NOT DISTINCT FROM x.organization_id
 WHERE x.id=p_campaign_id AND x.staff_id=p_staff_id AND p_account_id IN (x.account_id,x.secondary_account_id)
   AND x.runtime_claim_token=p_claim_token AND x.runtime_unit_token=p_unit_token
   AND x.runtime_unit_claimed_at IS NOT NULL FOR UPDATE OF x;
 IF NOT FOUND THEN RAISE EXCEPTION 'action_result_claim_invalid'; END IF;
 IF p_input_data_id IS NOT NULL AND NOT COALESCE(p_input_data_id=ANY(c.runtime_unit_input_data_ids),false)
 THEN RAISE EXCEPTION 'action_result_input_not_in_unit'; END IF;
 IF p_input_patch ? 'suppressedResult' THEN
   v_effect:=p_input_patch->'suppressedResult'->>'inputEffect';
   IF v_effect IS NULL OR v_effect NOT IN ('complete','pause','requeue','none') THEN RAISE EXCEPTION 'action_result_suppression_invalid'; END IF;
   v_committed:=COALESCE(p_input_patch->'suppressedResult'->>'operationState','unknown')<>'not_committed';
 END IF;
 SELECT coalesce(array_agg(DISTINCT id ORDER BY id),'{}'::bigint[]) INTO v_ids FROM unnest(p_detail_ids) id;
 IF cardinality(v_ids)<>cardinality(p_detail_ids) THEN RAISE EXCEPTION 'action_result_settlement_duplicate_id'; END IF;
 IF (SELECT count(*) FROM public.auto_campaign_details WHERE id=ANY(v_ids) AND campaign_id=p_campaign_id
    AND account_id=p_account_id AND input_data_id IS NOT DISTINCT FROM p_input_data_id
    AND policy_snapshot->>'unitKey'=md5(p_unit_token::text))<>cardinality(v_ids)
 THEN RAISE EXCEPTION 'action_result_settlement_scope_invalid'; END IF;
 IF EXISTS (SELECT 1 FROM public.auto_campaign_details sibling
   WHERE sibling.campaign_id=p_campaign_id
     AND ((p_input_data_id IS NULL AND sibling.input_data_id IS NULL) OR sibling.input_data_id=p_input_data_id)
     AND sibling.policy_snapshot->>'unitKey'=md5(p_unit_token::text) AND NOT sibling.id=ANY(v_ids))
 THEN RAISE EXCEPTION 'action_result_settlement_incomplete'; END IF;
 FOR d IN SELECT * FROM public.auto_campaign_details WHERE id=ANY(v_ids) ORDER BY id FOR UPDATE LOOP
   v_reset_before:=v_reset_before OR COALESCE(d.policy_snapshot->'badTargetResetBefore'='true'::jsonb,false);
   IF d.policy_snapshot->>'badTargetEffect'='increment' THEN v_bad:='increment';
   ELSIF d.policy_snapshot->>'badTargetEffect'='reset' AND v_bad='ignore' THEN v_bad:='reset'; END IF;
   IF d.policy_snapshot->>'inputEffect'='pause' THEN v_effect:='pause';
   ELSIF d.policy_snapshot->>'inputEffect'='requeue' AND v_effect<>'pause' THEN v_effect:='requeue';
   ELSIF d.policy_snapshot->>'inputEffect'='complete' AND v_effect='none' THEN v_effect:='complete'; END IF;
   v_committed:=v_committed OR d.policy_snapshot->>'operationState'<>'not_committed';
   IF d.policy_snapshot ? 'settlement' THEN
     IF v_existing IS NOT NULL AND v_existing IS DISTINCT FROM d.policy_snapshot->'settlement'
     THEN RAISE EXCEPTION 'action_result_settlement_conflict'; END IF;
     v_existing:=d.policy_snapshot->'settlement';
   END IF;
 END LOOP;
 IF v_committed AND v_effect='requeue' THEN v_effect:='pause'; END IF;
 IF v_existing IS NOT NULL THEN
   IF v_existing->'detailIds' IS DISTINCT FROM to_jsonb(v_ids)
   THEN RAISE EXCEPTION 'action_result_settlement_conflict'; END IF;
   v_settlement:=v_existing; v_count:=(v_existing->>'badTargetCount')::integer;
 ELSE
   IF v_bad='increment' THEN
     INSERT INTO public.auto_campaign_error_state(campaign_id,count_consecutive_bad_targets,last_input_data_id,last_reason,last_bad_target_at,updated_at)
     VALUES(p_campaign_id,1,p_input_data_id,left(p_reason,2000),now(),now())
     ON CONFLICT(campaign_id) DO UPDATE SET count_consecutive_bad_targets=CASE WHEN v_reset_before THEN 1 ELSE auto_campaign_error_state.count_consecutive_bad_targets+1 END,
       last_input_data_id=EXCLUDED.last_input_data_id,last_reason=EXCLUDED.last_reason,last_bad_target_at=now(),updated_at=now()
     RETURNING count_consecutive_bad_targets INTO v_count;
   ELSIF v_bad='reset' OR v_reset_before THEN
     INSERT INTO public.auto_campaign_error_state(campaign_id,count_consecutive_bad_targets,last_reason,updated_at)
     VALUES(p_campaign_id,0,NULL,now()) ON CONFLICT(campaign_id) DO UPDATE
       SET count_consecutive_bad_targets=0,last_reason=NULL,updated_at=now() RETURNING count_consecutive_bad_targets INTO v_count;
   ELSE
     SELECT count_consecutive_bad_targets INTO v_count FROM public.auto_campaign_error_state WHERE campaign_id=p_campaign_id;
     v_count:=COALESCE(v_count,0);
   END IF;
   v_settlement:=jsonb_build_object('detailIds',v_ids,'badTargetEffect',v_bad,'badTargetResetBefore',v_reset_before,'badTargetCount',v_count,'inputEffect',v_effect,'inputApplied',false);
 END IF;
 IF p_input_patch IS NOT NULL AND p_input_data_id IS NOT NULL AND NOT COALESCE((p_input_patch->>'deferInput')::boolean,false) AND NOT (v_settlement->>'inputApplied')::boolean THEN
   v_status:=CASE v_effect WHEN 'complete' THEN 'hoàn thành' WHEN 'pause' THEN 'tạm dừng' WHEN 'requeue' THEN 'chờ xử lý' ELSE i.status END;
   -- Existing cancellation/account/opt-out guards may strengthen, never weaken,
   -- the configured decision. A completed/unknown operation cannot be requeued.
   IF p_input_patch->>'status'='tạm dừng' THEN v_status:='tạm dừng'; END IF;
   IF p_input_patch->>'status'='chờ xử lý' AND v_effect<>'pause' THEN v_status:=CASE WHEN v_committed THEN 'tạm dừng' ELSE 'chờ xử lý' END; END IF;
   IF i.status='tạm dừng' THEN v_status:='tạm dừng'; END IF;
   UPDATE public.auto_campaign_input_data SET status=v_status,
     note=CASE WHEN p_input_patch ? 'note' THEN p_input_patch->>'note' ELSE note END,
     date_action=CASE WHEN v_status='hoàn thành' THEN now() ELSE date_action END
   WHERE id=p_input_data_id RETURNING * INTO i;
   v_settlement:=v_settlement || jsonb_build_object('inputApplied',true,'inputStatus',v_status);
 END IF;
 UPDATE public.auto_campaign_details SET policy_snapshot=jsonb_set(policy_snapshot,'{settlement}',v_settlement) WHERE id=ANY(v_ids);
 RETURN jsonb_build_object('settlement',v_settlement,'input',CASE WHEN p_input_data_id IS NULL THEN NULL ELSE to_jsonb(i) END);
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_settle_campaign_run_unit_v2(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_runtime_unit_token uuid, p_requeue_unstarted boolean)
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, db_now timestamp with time zone, vietnam_date_key date, requeued_count integer)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_organization_id bigint;
  v_campaign_found boolean := false;
  v_campaign_status text;
  v_account_status text;
  v_account_platform text;
  v_account_is_zalo_web boolean;
  v_account_is_zalo_server boolean;
  v_runtime_owner_matches boolean;
  v_stored_unit_token uuid;
  v_stored_unit_vietnam_date date;
  v_stored_unit_claimed_at timestamptz;
  v_stored_unit_input_data_ids bigint[];
  v_optimistic_input_data_ids bigint[];
  v_now timestamptz := clock_timestamp();
  v_vietnam_date date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  v_requeued_count integer := 0;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'campaign, account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'runtime target must be desktop or server';
  END IF;
  IF p_runtime_unit_token IS NULL THEN
    RAISE EXCEPTION 'runtime unit token is required';
  END IF;
  IF p_requeue_unstarted IS NULL THEN
    RAISE EXCEPTION 'requeue-unstarted decision is required';
  END IF;

  -- Settlement is cleanup: an inactive staff/capability must not strand an
  -- exact token, but the staff/organization/account scope remains mandatory.
  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
  FOR SHARE OF staff;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', NULL::text, NULL::text,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  -- Read the immutable payload after the advisory lock, lock only those rows,
  -- then lock/recheck the campaign. This preserves the canonical input-first
  -- order used by control and run-unit claims.
  SELECT campaign.runtime_unit_input_data_ids
  INTO v_optimistic_input_data_ids
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    );

  IF cardinality(COALESCE(v_optimistic_input_data_ids, ARRAY[]::bigint[])) > 0 THEN
    PERFORM input_data.id
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.id = ANY(v_optimistic_input_data_ids)
      AND input_data.campaign_id = p_campaign_id
    ORDER BY input_data.id
    FOR UPDATE OF input_data;
  END IF;

  SELECT
    campaign.status,
    account.status,
    lower(btrim(COALESCE(account.flatform_type, ''))),
    COALESCE(account.is_zalo_show_web, false),
    COALESCE(account.is_zalo_server, false),
    campaign.runtime_unit_token,
    campaign.runtime_unit_vietnam_date,
    campaign.runtime_unit_claimed_at,
    campaign.runtime_unit_input_data_ids
  INTO
    v_campaign_status,
    v_account_status,
    v_account_platform,
    v_account_is_zalo_web,
    v_account_is_zalo_server,
    v_stored_unit_token,
    v_stored_unit_vietnam_date,
    v_stored_unit_claimed_at,
    v_stored_unit_input_data_ids
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF campaign, account;
  v_campaign_found := FOUND;

  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  IF NOT v_campaign_found THEN
    RETURN QUERY SELECT
      false, 'not_found', NULL::text, NULL::text,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;

  v_runtime_owner_matches := NOT (
    (v_runtime_target = 'server' AND (
      v_account_platform <> 'zalo'
      OR v_account_is_zalo_web
      OR NOT v_account_is_zalo_server
    ))
    OR (v_runtime_target = 'desktop' AND (
      v_account_platform = 'zalo' AND v_account_is_zalo_server
    ))
  );

  IF v_stored_unit_token IS NULL THEN
    IF NOT v_runtime_owner_matches THEN
      RETURN QUERY SELECT
        false, 'runtime_not_owner', v_campaign_status, v_account_status,
        v_now, v_vietnam_date, 0;
    ELSIF v_stored_unit_vietnam_date IS NOT NULL
      OR v_stored_unit_claimed_at IS NOT NULL
      OR v_stored_unit_input_data_ids IS NOT NULL
    THEN
      RETURN QUERY SELECT
        false, 'unit_lease_corrupt', v_campaign_status, v_account_status,
        v_now, v_vietnam_date, 0;
    ELSE
      -- Idempotent terminal result for a settlement response lost after the
      -- lease was cleared. There is no active token this caller can mutate.
      RETURN QUERY SELECT
        true, 'already_settled', v_campaign_status, v_account_status,
        v_now, v_vietnam_date, 0;
    END IF;
    RETURN;
  END IF;

  IF v_stored_unit_token IS DISTINCT FROM p_runtime_unit_token THEN
    RETURN QUERY SELECT
      false, 'unit_lease_mismatch', v_campaign_status, v_account_status,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;
  -- The exact opaque token remains authorized to clean up after mutable
  -- account subtype/capability/control changes; no other token can cross it.
  IF v_stored_unit_vietnam_date IS NULL
    OR v_stored_unit_claimed_at IS NULL
    OR v_stored_unit_input_data_ids IS NULL
  THEN
    RETURN QUERY SELECT
      false, 'unit_lease_corrupt', v_campaign_status, v_account_status,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;

  IF v_account_platform='facebook' THEN PERFORM private.facebook_random_unit_settled(p_campaign_id,p_account_id,p_runtime_unit_token,p_requeue_unstarted); END IF;

  -- Win the token CAS before mutating even the stored input set. Both changes
  -- remain one transaction, so callers can never observe a cleared lease with
  -- only a partial requeue.
  UPDATE public.auto_campaigns AS campaign
  SET runtime_unit_token = NULL,
    runtime_unit_vietnam_date = NULL,
    runtime_unit_claimed_at = NULL,
    runtime_unit_input_data_ids = NULL,
    updated_at = v_now
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND campaign.runtime_unit_token = p_runtime_unit_token;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      false, 'unit_lease_mismatch', v_campaign_status, v_account_status,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;

  IF p_requeue_unstarted
    AND cardinality(v_stored_unit_input_data_ids) > 0
  THEN
    UPDATE public.auto_campaign_input_data AS input_data
    SET status = 'chờ xử lý', date_action = NULL
    WHERE input_data.id = ANY(v_stored_unit_input_data_ids)
      AND input_data.campaign_id = p_campaign_id
      AND input_data.status = 'đang chạy';
    GET DIAGNOSTICS v_requeued_count = ROW_COUNT;
  END IF;

  RETURN QUERY SELECT
    true,
    CASE WHEN p_requeue_unstarted
      THEN 'requeued_unstarted'
      ELSE 'settled'
    END,
    v_campaign_status,
    v_account_status,
    v_now,
    v_vietnam_date,
    v_requeued_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_staff_access(p_staff_id bigint, p_username text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.org_staff%ROWTYPE; o public.org_organization%ROWTYPE;
BEGIN
  SELECT * INTO s FROM public.org_staff WHERE id=p_staff_id AND username=p_username AND password=p_password;
  IF NOT FOUND THEN RAISE EXCEPTION 'staff_auth_invalid'; END IF;
  SELECT * INTO STRICT o FROM public.org_organization WHERE id=s.organization_id;
  RETURN jsonb_build_object('isAdmin',s.is_admin IS TRUE AND s.is_active AND s.deleted_at IS NULL,
    'isActive',s.is_active AND s.deleted_at IS NULL,'timeAllowed',public.aka_agent_staff_time_allowed(s.id),
    'expirationDate',s.expiration_date,'useStaffExpiration',o.use_staff_expiration,'useOrganizationExpiration',NOT o.use_staff_expiration);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_staff_management(p_actor_id bigint, p_username text, p_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '12s'
AS $function$
#variable_conflict use_variable
DECLARE
  actor public.org_staff%ROWTYPE; org public.org_organization%ROWTYPE;
  target public.org_staff%ROWTYPE; grp public.org_group%ROWTYPE;
  request public.auto_staff_management_requests%ROWTYPE;
  result jsonb; obj jsonb; ids bigint[]; id bigint; parent_id bigint; group_id bigint;
  request_id uuid; revision text; phone text; label text; allowed text[];
  root_id bigint; root_count integer;
  mutation boolean; total bigint; offset_rows integer; group_ids bigint[]; stamp timestamptz:=clock_timestamp();
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('list','saveGroup','saveStaff','setStatus','revealPassword','prepareDevices','resetDevices') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
  allowed:=CASE p_action
    WHEN 'list' THEN ARRAY['search','groupId','status','page']
    WHEN 'saveGroup' THEN ARRAY['id','name','parentId','expectedVersion','requestId']
    WHEN 'saveStaff' THEN ARRAY['id','name','phone','groupId','isDepartmentManager','expectedVersion','requestId']
    WHEN 'setStatus' THEN ARRAY['targets','isActive','requestId']
    WHEN 'revealPassword' THEN ARRAY['id']
    WHEN 'prepareDevices' THEN ARRAY['ids']
    ELSE ARRAY['targets','requestId'] END;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_data) k WHERE NOT k=ANY(allowed)) THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
  SELECT s.* INTO actor FROM public.org_staff s WHERE s.id=p_actor_id AND s.username=p_username AND s.password=p_password;
  IF NOT FOUND OR actor.is_admin IS NOT TRUE OR NOT public.aka_agent_staff_time_allowed(actor.id) THEN RAISE EXCEPTION 'staff_access_denied'; END IF;
  mutation:=p_action IN ('saveGroup','saveStaff','setStatus','resetDevices');
  IF mutation THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('aka-agent-staff-management:'||actor.organization_id::text,0));
    IF p_action IN ('saveGroup','saveStaff') THEN
      -- Share Chat's organization lock before actor/group/staff rows, including manager replacement.
      PERFORM pg_advisory_xact_lock(hashtextextended('aka-agent-chat:workspace-staff:'||actor.organization_id::text,0));
    END IF;
  END IF;
  -- Revalidate after waiting. Keep the authorizing row locked through commit.
  SELECT s.* INTO actor FROM public.org_staff s WHERE s.id=p_actor_id AND s.username=p_username AND s.password=p_password FOR SHARE;
  IF NOT FOUND OR actor.is_admin IS NOT TRUE OR NOT public.aka_agent_staff_time_allowed(actor.id) THEN RAISE EXCEPTION 'staff_access_denied'; END IF;
  SELECT o.* INTO STRICT org FROM public.org_organization o WHERE o.id=actor.organization_id FOR SHARE;
  IF mutation THEN
    request_id:=(p_data->>'requestId')::uuid;
    IF request_id IS NULL THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    SELECT * INTO request FROM public.auto_staff_management_requests WHERE auto_staff_management_requests.request_id=request_id;
    IF FOUND THEN
      IF request.actor_id<>actor.id OR request.organization_id<>org.id OR request.action<>p_action OR request.payload IS DISTINCT FROM p_data THEN RAISE EXCEPTION 'staff_conflict'; END IF;
      RETURN request.result;
    END IF;
  END IF;

  IF p_action='list' THEN
    IF length(coalesce(p_data->>'search',''))>200 OR coalesce(p_data->>'status','all') NOT IN ('all','active','locked','expired') THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    offset_rows:=greatest(0,coalesce((p_data->>'page')::integer,0))*100;
    group_id:=(p_data->>'groupId')::bigint;
    IF group_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.org_group WHERE org_group.id=group_id AND organization_id=org.id) THEN RAISE EXCEPTION 'staff_not_found'; END IF;
      WITH RECURSIVE tree AS (SELECT g.id FROM public.org_group g WHERE g.id=group_id AND g.organization_id=org.id
        UNION SELECT g.id FROM public.org_group g JOIN tree t ON g.parent_id=t.id WHERE g.organization_id=org.id)
      SELECT array_agg(t.id) INTO group_ids FROM tree t;
    END IF;
    WITH rows AS MATERIALIZED (SELECT public.aka_agent_staff_management_row(s.id) row FROM public.org_staff s
      WHERE s.organization_id=org.id AND s.deleted_at IS NULL
      AND (coalesce(p_data->>'search','')='' OR strpos(lower(s.name||' '||s.phone||' '||s.username),lower(p_data->>'search'))>0)
      AND (group_id IS NULL OR EXISTS (SELECT 1 FROM public.org_group_staff gs WHERE gs.staff_id=s.id AND gs.organization_id=org.id AND gs.group_id=ANY(group_ids)))),
    filtered AS (SELECT row FROM rows WHERE coalesce(p_data->>'status','all')='all' OR row->>'status'=p_data->>'status'),
    page AS (SELECT row FROM filtered ORDER BY (row->>'id')::bigint OFFSET offset_rows LIMIT 100)
    SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(row ORDER BY (row->>'id')::bigint) FROM page),'[]'::jsonb),
      'total',(SELECT count(*) FROM filtered),'page',offset_rows/100) INTO result;
    SELECT count(*) INTO total FROM public.org_staff s WHERE s.organization_id=org.id AND s.deleted_at IS NULL;
    result:=result||jsonb_build_object('organization',jsonb_build_object('id',org.id,'name',org.name,'maxStaff',org.max_staff,
      'staffCount',total,'staffDurationDays',coalesce(org.staff_duration_days,365),'useStaffExpiration',org.use_staff_expiration,'useOrganizationExpiration',NOT org.use_staff_expiration,
      'expirationDate',(SELECT max(p.expiration_date) FROM public.org_organization_product p WHERE p.organization_id=org.id AND NOT p.is_deleted AND p.product_id IN (3,10,13,16,17,18)),
      'today',timezone('Asia/Ho_Chi_Minh',stamp)::date),
      'groups',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'parentId',g.parent_id,'version',g.xmin::text,
        'managers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'name',m.name) ORDER BY m.id)
          FROM public.org_staff m WHERE m.organization_id=org.id AND m.deleted_at IS NULL
          AND EXISTS(SELECT 1 FROM public.org_group_staff gm WHERE gm.group_id=g.id AND gm.organization_id=org.id AND gm.staff_id=m.id AND gm.is_admin IS TRUE)),'[]'::jsonb),
        'staffCount',(SELECT count(DISTINCT gs.staff_id) FROM public.org_group_staff gs JOIN public.org_staff s ON s.id=gs.staff_id
          WHERE gs.group_id=g.id AND gs.organization_id=org.id AND s.organization_id=org.id AND s.deleted_at IS NULL)) ORDER BY g.id)
        FROM public.org_group g WHERE g.organization_id=org.id),'[]'::jsonb));

  ELSIF p_action='saveGroup' THEN
    id:=(p_data->>'id')::bigint; parent_id:=(p_data->>'parentId')::bigint; label:=btrim(p_data->>'name');
    IF label IS NULL OR length(label) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    SELECT count(*),min(g.id) INTO root_count,root_id FROM public.org_group g WHERE g.organization_id=org.id AND g.parent_id IS NULL;
    IF root_count>1 THEN RAISE EXCEPTION 'staff_group_multiple_roots'; END IF;
    IF root_id IS NULL THEN
      INSERT INTO public.org_group(organization_id,name,parent_id) VALUES(org.id,org.name,NULL) RETURNING org_group.id INTO root_id;
    END IF;
    -- NULL is the legacy Desktop value for 'directly under the organization'.
    parent_id:=coalesce(parent_id,root_id);
    IF parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_group g WHERE g.id=parent_id AND g.organization_id=org.id) THEN RAISE EXCEPTION 'staff_not_found'; END IF;
    IF id IS NOT NULL THEN
      SELECT * INTO grp FROM public.org_group g WHERE g.id=id AND g.organization_id=org.id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'staff_not_found'; END IF;
      IF grp.parent_id IS NULL THEN RAISE EXCEPTION 'staff_group_root_read_only'; END IF;
      SELECT g.xmin::text INTO revision FROM public.org_group g WHERE g.id=id;
      IF revision IS DISTINCT FROM p_data->>'expectedVersion' THEN RAISE EXCEPTION 'staff_conflict'; END IF;
      IF parent_id IS NOT NULL AND EXISTS (WITH RECURSIVE descendants AS (
        SELECT g.id FROM public.org_group g WHERE g.id=id AND g.organization_id=org.id
        UNION SELECT g.id FROM public.org_group g JOIN descendants d ON g.parent_id=d.id WHERE g.organization_id=org.id)
        SELECT 1 FROM descendants d WHERE d.id=parent_id) THEN RAISE EXCEPTION 'staff_group_cycle'; END IF;
      UPDATE public.org_group g SET name=label,parent_id=save_parent.parent_id,updated_at=stamp
        FROM (SELECT parent_id) save_parent WHERE g.id=id;
    ELSE
      INSERT INTO public.org_group(organization_id,name,parent_id) VALUES(org.id,label,parent_id) RETURNING org_group.id INTO id;
    END IF;
    result:=jsonb_build_object('id',id);

  ELSIF p_action='saveStaff' THEN
    id:=(p_data->>'id')::bigint;group_id:=(p_data->>'groupId')::bigint;label:=btrim(p_data->>'name');phone:=public.normalize_phone(p_data->>'phone');
    IF label IS NULL OR length(label) NOT BETWEEN 1 AND 200 OR phone IS NULL OR phone !~ '^0[0-9]{9,10}$' OR group_id IS NULL THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    IF p_data ? 'isDepartmentManager' AND jsonb_typeof(p_data->'isDepartmentManager') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.org_group g WHERE g.id=group_id AND g.organization_id=org.id) THEN RAISE EXCEPTION 'staff_not_found'; END IF;
    IF EXISTS(SELECT 1 FROM public.org_staff s WHERE s.organization_id=org.id AND public.normalize_phone(s.phone)=phone AND (id IS NULL OR s.id<>id)) THEN RAISE EXCEPTION 'staff_phone_exists'; END IF;
    IF id IS NULL THEN
      SELECT count(*) INTO total FROM public.org_staff s WHERE s.organization_id=org.id AND s.deleted_at IS NULL;
      IF total>=org.max_staff THEN RAISE EXCEPTION 'staff_quota_full'; END IF;
      INSERT INTO public.org_staff(organization_id,name,phone,username,password,is_active,is_admin,created_at,updated_at,expiration_date)
      VALUES(org.id,label,phone,org.id::text||'.'||phone,'123456',true,false,stamp,stamp,
        (timezone('Asia/Ho_Chi_Minh',stamp)::date+coalesce(org.staff_duration_days,365)+1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')
      RETURNING org_staff.id INTO id;
    ELSE
      SELECT * INTO target FROM public.org_staff s WHERE s.id=id AND s.organization_id=org.id AND s.deleted_at IS NULL FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'staff_not_found'; END IF;
      IF public.aka_agent_staff_management_row(id)->>'version' IS DISTINCT FROM p_data->>'expectedVersion' THEN RAISE EXCEPTION 'staff_conflict'; END IF;
      UPDATE public.org_staff s SET name=label,phone=save_phone.phone,updated_at=stamp FROM (SELECT phone) save_phone WHERE s.id=id;
    END IF;
    DELETE FROM public.org_group_staff gs WHERE gs.staff_id=id AND gs.organization_id=org.id AND gs.group_id<>group_id;
    IF NOT EXISTS(SELECT 1 FROM public.org_group_staff gs WHERE gs.staff_id=id AND gs.organization_id=org.id AND gs.group_id=group_id) THEN
      INSERT INTO public.org_group_staff(organization_id,staff_id,group_id,is_admin) VALUES(org.id,id,group_id,false);
    END IF;
    -- Optional for legacy clients: omission keeps the previous membership behavior.
    -- Explicit true replaces every current manager of the chosen department, as Chat does.
    IF p_data ? 'isDepartmentManager' THEN
      IF (p_data->>'isDepartmentManager')::boolean THEN
        UPDATE public.org_group_staff gs SET is_admin=false
          WHERE gs.organization_id=org.id AND gs.group_id=group_id AND gs.staff_id<>id AND gs.is_admin IS TRUE;
      END IF;
      UPDATE public.org_group_staff gs SET is_admin=(p_data->>'isDepartmentManager')::boolean
        WHERE gs.organization_id=org.id AND gs.group_id=group_id AND gs.staff_id=id
          AND gs.is_admin IS DISTINCT FROM (p_data->>'isDepartmentManager')::boolean;
    END IF;
    result:=public.aka_agent_staff_management_row(id);

  ELSIF p_action='revealPassword' THEN
    SELECT s.password INTO revision FROM public.org_staff s WHERE s.id=(p_data->>'id')::bigint AND s.organization_id=org.id AND s.deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'staff_not_found'; END IF;
    result:=jsonb_build_object('password',revision);

  ELSE
    IF p_action='prepareDevices' THEN
      IF jsonb_typeof(p_data->'ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
      SELECT array_agg(DISTINCT value::bigint ORDER BY value::bigint) INTO ids FROM jsonb_array_elements_text(p_data->'ids');
    ELSE
      IF jsonb_typeof(p_data->'targets') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
      SELECT array_agg(DISTINCT (value->>'id')::bigint ORDER BY (value->>'id')::bigint) INTO ids FROM jsonb_array_elements(p_data->'targets');
    END IF;
    IF coalesce(cardinality(ids),0) NOT BETWEEN 1 AND 100 OR array_position(ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    IF p_action='prepareDevices' THEN
      PERFORM s.id FROM public.org_staff s WHERE s.id=ANY(ids) AND s.organization_id=org.id ORDER BY s.id FOR SHARE;
    ELSE
      PERFORM s.id FROM public.org_staff s WHERE s.id=ANY(ids) AND s.organization_id=org.id ORDER BY s.id FOR UPDATE;
    END IF;
    IF (SELECT count(*) FROM public.org_staff s WHERE s.id=ANY(ids) AND s.organization_id=org.id AND s.deleted_at IS NULL)<>cardinality(ids) THEN RAISE EXCEPTION 'staff_not_found'; END IF;
    IF p_action='prepareDevices' THEN
      SELECT jsonb_build_object('items',jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'username',s.username,
        'version',s.xmin::text,'isBound',s.aka_agent_device_fingerprint_hash IS NOT NULL,
        'label',presence.device_label,'platform',presence.device_platform,'lastSeenAt',presence.last_seen_at) ORDER BY s.id)) INTO result
      FROM public.org_staff s LEFT JOIN LATERAL (SELECT p.device_label,p.device_platform,p.last_seen_at FROM public.auto_staff_device_presence p
        WHERE p.staff_id=s.id AND p.organization_id=org.id ORDER BY p.last_seen_at DESC LIMIT 1) presence ON true WHERE s.id=ANY(ids);
    ELSE
      IF jsonb_array_length(p_data->'targets')<>cardinality(ids) THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
      FOR obj IN SELECT value FROM jsonb_array_elements(p_data->'targets') LOOP
        IF jsonb_typeof(obj) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(obj) k WHERE k NOT IN ('id','expectedVersion')) THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
        IF (obj->>'id')::bigint IS NULL OR obj->>'expectedVersion' IS NULL THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
        IF p_action='setStatus' THEN revision:=public.aka_agent_staff_management_row((obj->>'id')::bigint)->>'version';
        ELSE SELECT s.xmin::text INTO revision FROM public.org_staff s WHERE s.id=(obj->>'id')::bigint; END IF;
        IF revision IS DISTINCT FROM obj->>'expectedVersion' THEN RAISE EXCEPTION 'staff_conflict'; END IF;
      END LOOP;
      IF p_action='setStatus' THEN
        IF jsonb_typeof(p_data->'isActive') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
        IF NOT (p_data->>'isActive')::boolean AND (actor.id=ANY(ids) OR NOT EXISTS(SELECT 1 FROM public.org_staff s
          WHERE s.organization_id=org.id AND s.is_admin IS TRUE AND s.is_active AND s.deleted_at IS NULL AND NOT s.id=ANY(ids))) THEN RAISE EXCEPTION 'staff_admin_required'; END IF;
        UPDATE public.org_staff s SET is_active=(p_data->>'isActive')::boolean,updated_at=stamp WHERE s.id=ANY(ids);
      ELSE
        UPDATE public.org_staff s SET aka_agent_device_fingerprint_hash=NULL,updated_at=stamp
          WHERE s.id=ANY(ids) AND s.aka_agent_device_fingerprint_hash IS NOT NULL;
      END IF;
      result:=jsonb_build_object('count',cardinality(ids));
    END IF;
  END IF;
  IF mutation THEN
    INSERT INTO public.auto_staff_management_requests(request_id,actor_id,organization_id,action,payload,result)
      VALUES(request_id,actor.id,org.id,p_action,p_data,result);
  END IF;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_take_campaign_content_index(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_runtime_claim_token uuid, p_runtime_unit_token uuid, p_input_data_id bigint, p_action_code text, p_variant_count integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_org bigint;
  v_campaign public.auto_campaigns%ROWTYPE;
  v_input public.auto_campaign_input_data%ROWTYPE;
  v_raw text;
  v_index integer;
  v_first boolean;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0 OR p_runtime_target IS NULL
    OR p_runtime_target NOT IN ('desktop','server')
    OR p_runtime_claim_token IS NULL OR p_runtime_unit_token IS NULL
    OR p_action_code IS NULL OR btrim(p_action_code) = '' OR length(p_action_code) > 128
    OR p_variant_count IS NULL OR p_variant_count < 1
    OR (p_input_data_id IS NOT NULL AND p_input_data_id <= 0) THEN
    RAISE EXCEPTION 'campaign_content_invalid_arguments';
  END IF;

  SELECT organization_id INTO v_org FROM public.org_staff
  WHERE id=p_staff_id AND is_active IS TRUE FOR SHARE;
  IF v_org IS NULL THEN RAISE EXCEPTION 'campaign_content_not_owner'; END IF;

  -- Same lock order as unit claim: staff -> entitlement -> serialization -> input -> campaign/account.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('aka-agent-zalo-runtime-entitlement-mutation',0));
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);
  IF p_input_data_id IS NOT NULL THEN
    SELECT * INTO v_input FROM public.auto_campaign_input_data
    WHERE id=p_input_data_id AND campaign_id=p_campaign_id
      AND NOT COALESCE(is_delete,false) AND status='đang chạy' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'campaign_content_input_not_owned'; END IF;
  END IF;

  SELECT c.* INTO v_campaign FROM public.auto_campaigns c
  JOIN public.auto_accounts a ON a.id=c.account_id AND a.staff_id=c.staff_id
  WHERE c.id=p_campaign_id AND c.account_id=p_account_id AND c.staff_id=p_staff_id
    AND (c.organization_id IS NULL OR c.organization_id=v_org)
    AND (a.organization_id IS NULL OR a.organization_id=v_org)
    AND NOT COALESCE(c.is_delete,false) AND NOT COALESCE(a.is_delete,false)
    AND a.is_active IS TRUE AND a.login_status='đã đăng nhập'
    -- Server pause drains the already-claimed unit before releasing ownership.
    AND (p_runtime_target='server' OR (c.status='đang chạy' AND a.status='đang chạy'))
    AND c.runtime_claim_token=p_runtime_claim_token AND c.runtime_claim_target=p_runtime_target
    AND c.runtime_unit_token=p_runtime_unit_token AND c.runtime_unit_claimed_at IS NOT NULL
  FOR UPDATE OF c,a;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_content_not_owner'; END IF;
  IF p_input_data_id IS NOT NULL AND NOT COALESCE(p_input_data_id=ANY(v_campaign.runtime_unit_input_data_ids),false) THEN
    RAISE EXCEPTION 'campaign_content_input_not_in_unit';
  END IF;
  IF p_variant_count=1 THEN RETURN 0; END IF;

  v_first := p_input_data_id IS NULL OR NOT (v_input.content_rotation_indexes ? p_action_code);
  IF v_first THEN
    v_raw := v_campaign.content_rotation_indexes->>p_action_code;
    IF v_raw IS NULL AND v_campaign.action_id IN ('facebook_timeline_post','facebook_page_post')
      AND p_action_code IN ('fb_post_my_profile','fb_post_page') THEN
      v_raw := v_campaign.extra_settings->>'contentRotationIndex';
    END IF;
  ELSE
    v_raw := v_input.content_rotation_indexes->>p_action_code;
  END IF;
  -- Modulo the current snapshot size; changing templates does not clear state.
  v_index := CASE WHEN v_raw ~ '^[0-9]{1,16}$'
    THEN mod(v_raw::numeric,p_variant_count)::integer ELSE 0 END;
  IF v_first THEN
    UPDATE public.auto_campaigns SET content_rotation_indexes=jsonb_set(
      content_rotation_indexes,ARRAY[p_action_code],to_jsonb((v_index+1)%p_variant_count),true)
    WHERE id=p_campaign_id;
  END IF;
  IF p_input_data_id IS NOT NULL THEN
    UPDATE public.auto_campaign_input_data SET content_rotation_indexes=jsonb_set(
      content_rotation_indexes,ARRAY[p_action_code],to_jsonb((v_index+1)%p_variant_count),true)
    WHERE id=p_input_data_id;
  END IF;
  RETURN v_index;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_write_action_result_v1(p_staff_id bigint, p_campaign_id bigint, p_account_id bigint, p_claim_token uuid, p_unit_token uuid, p_result_key text, p_detail jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
 c public.auto_campaigns%ROWTYPE;
 d public.auto_campaign_details%ROWTYPE;
 p public.auto_account_action_status_policies%ROWTYPE;
 v_input_id bigint := (p_detail->>'input_data_id')::bigint;
 decision jsonb := p_detail->'policy_snapshot';
BEGIN
 IF p_staff_id IS NULL OR p_campaign_id IS NULL OR p_account_id IS NULL
   OR p_claim_token IS NULL OR p_unit_token IS NULL OR NULLIF(p_result_key,'') IS NULL
   OR jsonb_typeof(p_detail) IS DISTINCT FROM 'object'
   OR jsonb_typeof(decision) IS DISTINCT FROM 'object'
   OR jsonb_typeof(decision->'countsTowardLimit') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(decision->'resetErrorStreak') IS DISTINCT FROM 'boolean'
   OR decision->>'reportGroup' IS NULL OR decision->>'reportGroup' NOT IN ('success','failure','skipped','pending')
   OR decision->>'badTargetEffect' IS NULL OR decision->>'badTargetEffect' NOT IN ('increment','reset','ignore')
   OR decision->>'inputEffect' IS NULL OR decision->>'inputEffect' NOT IN ('complete','pause','requeue','none')
   OR decision->>'operationState' IS NULL OR decision->>'operationState' NOT IN ('committed','not_committed','unknown')
   OR decision ? 'settlement'
 THEN RAISE EXCEPTION 'action_result_payload_invalid'; END IF;
 -- Result commit drains an already claimed operation. Do not reject its error
 -- detail because an error policy just disabled the account or staff access.
 PERFORM 1 FROM public.org_staff WHERE id=p_staff_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'action_result_scope_invalid'; END IF;
 PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);
 IF v_input_id IS NOT NULL THEN
   PERFORM 1 FROM public.auto_campaign_input_data WHERE id=v_input_id AND campaign_id=p_campaign_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'action_result_input_invalid'; END IF;
 END IF;
 SELECT x.* INTO c FROM public.auto_campaigns x JOIN public.auto_accounts a ON a.id=p_account_id
   AND a.staff_id=x.staff_id AND a.organization_id IS NOT DISTINCT FROM x.organization_id
 WHERE x.id=p_campaign_id AND x.staff_id=p_staff_id
   AND p_account_id IN (x.account_id,x.secondary_account_id)
   AND x.runtime_claim_token=p_claim_token AND x.runtime_unit_token=p_unit_token
   AND x.runtime_unit_claimed_at IS NOT NULL FOR UPDATE OF x;
 IF NOT FOUND THEN RAISE EXCEPTION 'action_result_claim_invalid'; END IF;
 IF v_input_id IS NOT NULL AND NOT COALESCE(v_input_id=ANY(c.runtime_unit_input_data_ids),false)
 THEN RAISE EXCEPTION 'action_result_input_not_in_unit'; END IF;
 SELECT * INTO d FROM public.auto_campaign_details WHERE result_key=p_result_key;
 IF FOUND THEN
   IF d.campaign_id<>p_campaign_id OR d.account_id<>p_account_id
     OR d.input_data_id IS DISTINCT FROM v_input_id
     OR d.action_code IS DISTINCT FROM p_detail->>'action_code'
     OR d.status_id IS DISTINCT FROM (p_detail->>'status_id')::bigint
     OR d.policy_snapshot->>'unitKey' IS DISTINCT FROM md5(p_unit_token::text)
   THEN RAISE EXCEPTION 'action_result_key_conflict'; END IF;
   RETURN jsonb_build_object('detail',to_jsonb(d),'inserted',false);
 END IF;
 SELECT * INTO p FROM public.auto_account_action_status_policies
   WHERE id=(p_detail->>'action_status_policy_id')::bigint FOR SHARE;
 IF NOT FOUND OR p.status_id IS DISTINCT FROM (p_detail->>'status_id')::bigint
   OR (p.action_code IS NOT NULL AND p.action_code IS DISTINCT FROM p_detail->>'action_code')
 THEN RAISE EXCEPTION 'result_policy_identity_mismatch'; END IF;
 IF EXISTS (SELECT 1 FROM public.auto_campaign_details old
   WHERE old.campaign_id=p_campaign_id AND ((v_input_id IS NULL AND old.input_data_id IS NULL) OR old.input_data_id=v_input_id) AND old.policy_snapshot->>'unitKey'=md5(p_unit_token::text)
     AND old.policy_snapshot ? 'settlement')
 THEN RAISE EXCEPTION 'action_result_target_settled'; END IF;
 decision:=decision || jsonb_build_object('unitKey',md5(p_unit_token::text));
 -- Guard execution evidence even if a caller supplied an unsafe retry decision.
 IF decision->>'inputEffect'='requeue' AND decision->>'operationState'<>'not_committed'
 THEN decision:=jsonb_set(decision,'{inputEffect}','"pause"'); END IF;
 INSERT INTO public.auto_campaign_details(input_data_id,campaign_id,account_id,action_code,action_name,status,
   error_code,log,data,post_url,status_id,sub_status_id,action_status_policy_id,report_group,
   counts_toward_limit,policy_snapshot,result_key)
 VALUES(v_input_id,p_campaign_id,p_account_id,p_detail->>'action_code',p_detail->>'action_name',p_detail->>'status',
   NULLIF(p_detail->>'error_code',''),p_detail->>'log',p_detail->'data',p_detail->>'post_url',
   (p_detail->>'status_id')::bigint,(p_detail->>'sub_status_id')::bigint,p.id,decision->>'reportGroup',
   (decision->>'countsTowardLimit')::boolean,decision,p_result_key) RETURNING * INTO d;
 IF (decision->>'countsTowardLimit')::boolean THEN
   PERFORM public.increment_auto_account_action_count(p_account_id,d.action_code,1);
 END IF;
 IF (decision->>'resetErrorStreak')::boolean THEN
   UPDATE public.auto_account_error_state SET count_consecutive_errors=0,updated_at=now()
     WHERE account_id=p_account_id AND action_code=d.action_code;
 END IF;
 RETURN jsonb_build_object('detail',to_jsonb(d),'inserted',true);
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_yield_campaign_daily_boundary(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_runtime_claim_token uuid, p_claimed_vietnam_date date)
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, db_now timestamp with time zone, vietnam_date_key date, claimed_vietnam_date_key date, effective_stop_time time without time zone, boundary_at timestamp with time zone, day_changed boolean, running_input_count bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_now timestamptz;
  v_vietnam_date date;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_organization_id bigint;
  v_campaign_status text;
  v_account_status text;
  v_daily_stop_time time without time zone;
  v_campaign_is_delete boolean;
  v_account_is_delete boolean;
  v_account_platform text;
  v_account_is_zalo_web boolean;
  v_account_is_zalo_server boolean;
  v_stored_claim_token uuid;
  v_stored_claim_target text;
  v_stored_claim_vietnam_date date;
  v_stored_unit_token uuid;
  v_effective_stop_time time without time zone;
  v_boundary_at timestamptz;
  v_day_changed boolean;
  v_running_input_count bigint := 0;
  v_reason text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'campaign, account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'runtime target must be desktop or server';
  END IF;
  IF p_runtime_claim_token IS NULL OR p_claimed_vietnam_date IS NULL THEN
    RAISE EXCEPTION 'runtime claim token and Vietnam date are required';
  END IF;

  -- Yield is cleanup. Do not require staff.is_active or a live entitlement:
  -- capability loss must not strand a campaign/account in running state.
  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
  FOR SHARE OF staff;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    v_now := clock_timestamp();
    v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
    RETURN QUERY SELECT
      false, 'runtime_not_owner', NULL::text, NULL::text,
      v_now, v_vietnam_date, p_claimed_vietnam_date,
      NULL::time, NULL::timestamptz,
      v_vietnam_date > p_claimed_vietnam_date,
      0::bigint;
    RETURN;
  END IF;

  -- Use the same campaign-scoped serialization barrier as Server run-unit
  -- claims and Control pause/resume before touching input/campaign rows.
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  -- Wait for any in-flight unit row to become stable, but never mutate it.
  -- The runtime calls this RPC only after its current target/batch has settled.
  PERFORM input_data.id
  FROM public.auto_campaign_input_data AS input_data
  WHERE input_data.campaign_id = p_campaign_id
    AND COALESCE(input_data.is_delete, false) = false
    AND input_data.status = 'đang chạy'
  ORDER BY input_data.id
  FOR UPDATE OF input_data;

  PERFORM campaign_input.id
  FROM public.auto_campaign_inputs AS campaign_input
  WHERE campaign_input.campaign_id = p_campaign_id
    AND COALESCE(campaign_input.is_delete, false) = false
    AND campaign_input.status = 'đang chạy'
  ORDER BY campaign_input.id
  FOR UPDATE OF campaign_input;

  SELECT
    campaign.status,
    account.status,
    campaign.daily_stop_time,
    COALESCE(campaign.is_delete, false),
    COALESCE(account.is_delete, false),
    lower(btrim(COALESCE(account.flatform_type, ''))),
    COALESCE(account.is_zalo_show_web, false),
    COALESCE(account.is_zalo_server, false),
    campaign.runtime_claim_token,
    campaign.runtime_claim_target,
    campaign.runtime_claim_vietnam_date,
    campaign.runtime_unit_token
  INTO
    v_campaign_status,
    v_account_status,
    v_daily_stop_time,
    v_campaign_is_delete,
    v_account_is_delete,
    v_account_platform,
    v_account_is_zalo_web,
    v_account_is_zalo_server,
    v_stored_claim_token,
    v_stored_claim_target,
    v_stored_claim_vietnam_date,
    v_stored_unit_token
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF campaign, account;

  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      false, 'not_found', NULL::text, NULL::text,
      v_now, v_vietnam_date, p_claimed_vietnam_date,
      NULL::time, NULL::timestamptz,
      v_vietnam_date > p_claimed_vietnam_date,
      0::bigint;
    RETURN;
  END IF;

  v_effective_stop_time := LEAST(
    COALESCE(v_daily_stop_time, time '23:59:00'),
    time '23:59:00'
  );
  v_boundary_at := (
    p_claimed_vietnam_date + v_effective_stop_time
  ) AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_day_changed := v_vietnam_date > p_claimed_vietnam_date;

  SELECT
    (
      SELECT count(*)
      FROM public.auto_campaign_input_data AS input_data
      WHERE input_data.campaign_id = p_campaign_id
        AND COALESCE(input_data.is_delete, false) = false
        AND input_data.status = 'đang chạy'
    ) + (
      SELECT count(*)
      FROM public.auto_campaign_inputs AS campaign_input
      WHERE campaign_input.campaign_id = p_campaign_id
        AND COALESCE(campaign_input.is_delete, false) = false
        AND campaign_input.status = 'đang chạy'
    )
  INTO v_running_input_count;

  IF v_stored_unit_token IS NOT NULL THEN
    -- A durable lease is the authoritative in-flight marker, including for an
    -- empty-ID aggregate unit and after DB-first control changed visible state.
    v_reason := 'unit_still_running';
  ELSIF (v_runtime_target = 'server' AND (
      v_account_platform <> 'zalo'
      OR v_account_is_zalo_web
      OR NOT v_account_is_zalo_server
    ))
    OR (v_runtime_target = 'desktop' AND (
      v_account_platform = 'zalo' AND v_account_is_zalo_server
    ))
  THEN
    v_reason := 'runtime_not_owner';
  ELSIF v_campaign_is_delete THEN
    v_reason := 'campaign_deleted';
  ELSIF v_account_is_delete THEN
    v_reason := 'account_deleted';
  ELSIF v_campaign_status IS DISTINCT FROM 'đang chạy'
    OR v_account_status IS DISTINCT FROM 'đang chạy'
  THEN
    -- A DB-first running -> paused transition preserves the parent tuple, but
    -- visible control still wins so the owning executor performs its normal
    -- account-release cleanup instead of yielding or starting new work.
    v_reason := 'runtime_control_paused';
  ELSIF v_stored_claim_token IS DISTINCT FROM p_runtime_claim_token
    OR v_stored_claim_target IS DISTINCT FROM v_runtime_target
    OR v_stored_claim_vietnam_date IS DISTINCT FROM p_claimed_vietnam_date
  THEN
    -- While control remains running, mismatch wins over a newer run's input
    -- count so the stale executor cannot loop on unit_still_running.
    v_reason := 'runtime_claim_mismatch';
  ELSIF v_running_input_count > 0 THEN
    v_reason := 'unit_still_running';
  ELSIF p_claimed_vietnam_date > v_vietnam_date THEN
    v_reason := 'invalid_claimed_vietnam_date';
  ELSIF v_day_changed THEN
    v_reason := 'vietnam_day_changed';
  ELSIF v_now >= v_boundary_at THEN
    v_reason := CASE
      WHEN v_daily_stop_time IS NULL THEN 'daily_drain_due'
      ELSE 'daily_stop_due'
    END;
  ELSE
    v_reason := 'boundary_not_due';
  END IF;

  IF v_reason IN (
    'vietnam_day_changed',
    'daily_drain_due',
    'daily_stop_due'
  ) THEN
    UPDATE public.auto_campaigns AS campaign
    SET
      status = 'chờ xử lý',
      runtime_claim_token = NULL,
      runtime_claim_target = NULL,
      runtime_claim_vietnam_date = NULL,
      runtime_claimed_at = NULL,
      updated_at = v_now
    WHERE campaign.id = p_campaign_id
      AND campaign.status = 'đang chạy'
      AND campaign.runtime_claim_token = p_runtime_claim_token
      AND campaign.runtime_claim_target = v_runtime_target
      AND campaign.runtime_claim_vietnam_date = p_claimed_vietnam_date
      AND campaign.runtime_unit_token IS NULL;

    IF FOUND THEN
      UPDATE public.auto_accounts AS account
      SET
        status = 'chờ xử lý',
        updated_at = v_now
      WHERE account.id = p_account_id
        AND account.staff_id = p_staff_id
        AND account.status = 'đang chạy';

      v_campaign_status := 'chờ xử lý';
      IF FOUND THEN
        v_account_status := 'chờ xử lý';
      END IF;
      v_reason := 'yielded_' || v_reason;
    ELSE
      -- Defensive CAS result; row locks make this unlikely, but never report a
      -- successful yield when a newer status won.
      v_reason := 'runtime_control_paused';
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_reason IN (
      'yielded_vietnam_day_changed',
      'yielded_daily_drain_due',
      'yielded_daily_stop_due'
    ),
    v_reason,
    v_campaign_status,
    v_account_status,
    v_now,
    v_vietnam_date,
    p_claimed_vietnam_date,
    v_effective_stop_time,
    v_boundary_at,
    v_day_changed,
    v_running_input_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_zalo_phone_check_usage(p_staff_id bigint, p_organization_id bigint, p_account_id bigint, p_runtime_target text, p_claim_token uuid, p_consume boolean, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_capabilities record;
  v_today date;
  v_count integer := 0;
  v_limit integer := 600;
  v_setting text;
  v_allowed boolean;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0 OR p_organization_id IS NULL OR p_organization_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0 OR p_consume IS NULL
    OR p_runtime_target IS NULL OR p_runtime_target NOT IN ('desktop','server') THEN
    RAISE EXCEPTION 'phone_check_identity_invalid';
  END IF;
  IF p_auth_username IS NOT NULL OR p_auth_password IS NOT NULL THEN
    PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  ELSIF p_runtime_target <> 'server' OR p_claim_token IS NULL THEN
    RAISE EXCEPTION 'phone_check_auth_required';
  END IF;
  -- Preserve the existing scan lock order: staff, entitlement barrier, account.
  PERFORM 1 FROM public.org_staff s WHERE s.id=p_staff_id AND s.organization_id=p_organization_id
    AND s.is_active=true AND public.aka_agent_staff_time_allowed(s.id) FOR SHARE OF s;
  IF NOT FOUND THEN RAISE EXCEPTION 'phone_check_staff_invalid'; END IF;
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('aka-agent-zalo-runtime-entitlement-mutation',0));
  SELECT * INTO v_capabilities FROM public.resolve_organization_zalo_account_capabilities(p_organization_id);
  IF p_consume OR p_auth_username IS NULL THEN
    SELECT * INTO v_account FROM public.auto_accounts a
      WHERE a.id=p_account_id AND a.staff_id=p_staff_id
        AND (a.organization_id IS NULL OR a.organization_id=p_organization_id) FOR UPDATE OF a;
  ELSE
    SELECT * INTO v_account FROM public.auto_accounts a
      WHERE a.id=p_account_id AND a.staff_id=p_staff_id
        AND (a.organization_id IS NULL OR a.organization_id=p_organization_id);
  END IF;
  IF NOT FOUND OR COALESCE(v_account.is_delete,false)
    OR lower(btrim(COALESCE(v_account.flatform_type,''))) <> 'zalo' THEN
    RAISE EXCEPTION 'phone_check_account_invalid';
  END IF;
  IF (p_runtime_target='server' AND (v_account.is_zalo_server IS NOT TRUE OR v_account.is_zalo_show_web IS TRUE
      OR NOT COALESCE(v_capabilities.qr_enabled,false) OR NOT COALESCE(v_capabilities.server_enabled,false)))
    OR (p_runtime_target='desktop' AND (v_account.is_zalo_server IS TRUE
      OR (v_account.is_zalo_show_web IS TRUE AND NOT COALESCE(v_capabilities.web_enabled,false))
      OR (v_account.is_zalo_show_web IS NOT TRUE AND NOT COALESCE(v_capabilities.qr_enabled,false)))) THEN
    RAISE EXCEPTION 'phone_check_runtime_not_owner';
  END IF;
  IF (p_consume OR p_auth_username IS NULL) AND (p_claim_token IS NULL
    OR v_account.runtime_operation_claim_token IS DISTINCT FROM p_claim_token
    OR v_account.status IS DISTINCT FROM 'đang chạy'
    OR v_account.is_active IS NOT TRUE OR v_account.login_status IS DISTINCT FROM 'đã đăng nhập') THEN
    RAISE EXCEPTION 'phone_check_claim_invalid';
  END IF;
  -- Compute after acquiring the row lock, including a wait across midnight.
  v_today := timezone('Asia/Ho_Chi_Minh',clock_timestamp())::date;
  IF (v_account.zalo_phone_check_usage->>'date')::date > v_today THEN
    RAISE EXCEPTION 'phone_check_usage_date_in_future';
  END IF;
  IF v_account.zalo_phone_check_usage->>'date' = v_today::text THEN
    v_count := (v_account.zalo_phone_check_usage->>'count')::integer;
  END IF;
  SELECT value INTO v_setting FROM public.auto_system_settings
    WHERE key='zalo.phone_check.daily_limit' AND is_active=true AND is_secret=false;
  IF v_setting ~ '^[1-9][0-9]{0,9}$' AND v_setting::numeric <= 2147483647 THEN
    v_limit := v_setting::integer;
  END IF;
  v_allowed := v_count < v_limit;
  IF p_consume AND v_allowed THEN
    v_count := v_count+1;
    UPDATE public.auto_accounts SET zalo_phone_check_usage=jsonb_build_object('date',v_today,'count',v_count)
      WHERE id=p_account_id;
  END IF;
  RETURN jsonb_build_object('allowed',v_allowed,'date',v_today,'count',v_count,'limit',v_limit,
    'remaining',greatest(0,v_limit-v_count),
    'resetAt',((v_today+1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'));
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_non_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_platform text, p_previous_status text, p_claim_token uuid, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_platform text := lower(btrim(COALESCE(p_platform, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_platform NOT IN ('facebook', 'email') THEN
    RAISE EXCEPTION 'Non-Zalo runtime platform must be Facebook or Email';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  -- reset_desktop_running_statuses takes FOR UPDATE on this same row. The
  -- shared lock prevents a new account operation from entering recovery.
  SELECT staff.organization_id INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'staff_not_active'
    );
  END IF;

  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_found'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR v_account.is_active IS NOT TRUE
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> v_platform
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  -- Retrying the same client-generated token is idempotent after an ambiguous
  -- network response: the caller still owns this exact account-only claim.
  IF v_account.status = 'đang chạy'
    AND v_account.runtime_operation_claim_token = p_claim_token
  THEN
    RETURN jsonb_build_object(
      'claimed', true,
      'account_id', p_account_id,
      'previous_status', v_previous_status,
      'claim_token', p_claim_token,
      'platform', v_platform
    );
  END IF;

  IF (COALESCE(p_requires_login, true) AND v_account.login_status IS DISTINCT FROM 'đã đăng nhập')
    OR v_account.status IS DISTINCT FROM v_previous_status
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  UPDATE public.auto_accounts AS account
  SET
    status = 'đang chạy',
    runtime_operation_claim_token = p_claim_token,
    updated_at = now()
  WHERE account.id = p_account_id;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_previous_status,
    'claim_token', p_claim_token,
    'platform', v_platform
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_capabilities record;
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'staff_not_active'
    );
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT *
  INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(
    v_organization_id
  );

  SELECT account.*
  INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'account_not_found'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_inputs AS campaign_input
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = campaign_input.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign_input.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_input_data AS input_data
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = input_data.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND input_data.status = 'đang chạy'
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'work_running'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR v_account.is_active IS NOT TRUE
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> 'zalo'
    OR (
      COALESCE(p_requires_login, true)
      AND v_account.login_status <> 'đã đăng nhập'
    )
    OR v_account.status NOT IN ('chờ xử lý', 'tạm dừng')
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'account_not_available'
    );
  END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  IF (
    v_runtime_target = 'server'
    AND (
      v_is_web
      OR NOT v_is_server
      OR NOT COALESCE(v_capabilities.qr_enabled, false)
      OR NOT COALESCE(v_capabilities.server_enabled, false)
    )
  ) OR (
    v_runtime_target = 'desktop'
    AND (
      v_is_server
      OR (
        v_is_web
        AND NOT COALESCE(v_capabilities.web_enabled, false)
      )
      OR (
        NOT v_is_web
        AND NOT v_is_server
        AND NOT COALESCE(v_capabilities.qr_enabled, false)
      )
    )
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'runtime_not_owner'
    );
  END IF;

  UPDATE public.auto_accounts
  SET status = 'đang chạy', updated_at = now()
  WHERE id = p_account_id;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_account.status,
    'runtime_target', v_runtime_target
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text, p_claim_token uuid, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
  v_capabilities record;
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'staff_not_active'
    );
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT *
  INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(
    v_organization_id
  );

  SELECT account.*
  INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_found'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> 'zalo'
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  IF (
    v_runtime_target = 'server'
    AND (
      v_is_web
      OR NOT v_is_server
      OR NOT COALESCE(v_capabilities.qr_enabled, false)
      OR NOT COALESCE(v_capabilities.server_enabled, false)
    )
  ) OR (
    v_runtime_target = 'desktop'
    AND (
      v_is_server
      OR (
        v_is_web
        AND NOT COALESCE(v_capabilities.web_enabled, false)
      )
      OR (
        NOT v_is_web
        AND NOT v_is_server
        AND NOT COALESCE(v_capabilities.qr_enabled, false)
      )
    )
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'runtime_not_owner'
    );
  END IF;

  -- Retry of the same account-operation token remains idempotent after an
  -- ambiguous response. A campaign cannot form a unit while this account row
  -- is already owned/running by that token.
  IF v_account.status = 'đang chạy'
    AND v_account.runtime_operation_claim_token = p_claim_token
  THEN
    RETURN jsonb_build_object(
      'claimed', true,
      'account_id', p_account_id,
      'previous_status', v_previous_status,
      'claim_token', p_claim_token,
      'runtime_target', v_runtime_target
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_inputs AS campaign_input
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = campaign_input.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign_input.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_input_data AS input_data
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = input_data.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND input_data.status = 'đang chạy'
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'work_running'
    );
  END IF;

  IF v_account.status IS DISTINCT FROM v_previous_status
    OR (
      COALESCE(p_requires_login, true)
      AND (
        v_account.is_active IS NOT TRUE
        OR v_account.login_status IS DISTINCT FROM 'đã đăng nhập'
      )
    )
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  UPDATE public.auto_accounts AS account
  SET status = 'đang chạy',
    runtime_operation_claim_token = p_claim_token,
    updated_at = now()
  WHERE account.id = p_account_id
    AND account.status = v_previous_status;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_previous_status,
    'claim_token', p_claim_token,
    'runtime_target', v_runtime_target
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_campaign_zalo_realtime_group_event(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_group_id text, p_group_name text, p_trigger_type text, p_target_uid text, p_target_name text, p_event_time timestamp with time zone, p_schedule_at timestamp with time zone, p_raw_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(inserted boolean, event_id bigint, input_data_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id bigint;
  v_input_data_id bigint;
  v_organization_id bigint;
  v_capabilities record;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_target_uid text := btrim(COALESCE(p_target_uid, ''));
  v_target_name text := NULLIF(btrim(COALESCE(p_target_name, '')), '');
  v_group_id text := btrim(COALESCE(p_group_id, ''));
  v_group_name text := NULLIF(btrim(COALESCE(p_group_name, '')), '');
  v_schedule_at timestamptz := COALESCE(p_schedule_at, now());
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 THEN RAISE EXCEPTION 'campaign_id is required'; END IF;
  IF p_account_id IS NULL OR p_account_id <= 0 THEN RAISE EXCEPTION 'account_id is required'; END IF;
  IF p_staff_id IS NULL OR p_staff_id <= 0 THEN RAISE EXCEPTION 'staff_id is required'; END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN RAISE EXCEPTION 'runtime target must be desktop or server'; END IF;
  IF v_group_id = '' THEN RAISE EXCEPTION 'group_id is required'; END IF;
  IF v_target_uid = '' OR v_target_uid = '0' THEN RAISE EXCEPTION 'target_uid is required'; END IF;
  IF p_trigger_type NOT IN ('join', 'leave', 'interact') THEN RAISE EXCEPTION 'invalid trigger_type: %', p_trigger_type; END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN RAISE EXCEPTION 'active staff % was not found', p_staff_id; END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR (v_runtime_target = 'server'
      AND NOT COALESCE(v_capabilities.server_enabled, false))
  THEN RAISE EXCEPTION 'runtime_not_owner'; END IF;

  PERFORM 1
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND campaign.action_id = 'zalo_message_group_realtime'
    AND campaign.status IN ('chờ xử lý', 'đang chạy')
    AND COALESCE(campaign.is_delete, false) = false
  FOR SHARE OF campaign;
  IF NOT FOUND THEN RAISE EXCEPTION 'runtime_control_paused'; END IF;

  PERFORM 1
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND (
      (v_runtime_target = 'server' AND COALESCE(account.is_zalo_server, false) = true)
      OR (v_runtime_target = 'desktop' AND COALESCE(account.is_zalo_server, false) = false)
    )
    AND account.is_active = true
    AND account.status IN ('chờ xử lý', 'đang chạy')
    AND COALESCE(account.is_delete, false) = false
  FOR SHARE OF account;
  IF NOT FOUND THEN RAISE EXCEPTION 'runtime_control_paused'; END IF;

  INSERT INTO public.auto_campaign_zalo_realtime_group_events (
    campaign_id, account_id, group_id, group_name, trigger_type,
    target_uid, target_name, event_time, raw_payload
  ) VALUES (
    p_campaign_id, p_account_id, v_group_id, v_group_name, p_trigger_type,
    v_target_uid, v_target_name, COALESCE(p_event_time, now()), COALESCE(p_raw_payload, '{}'::jsonb)
  ) ON CONFLICT (campaign_id, target_uid) DO NOTHING
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    SELECT event.id, event.input_data_id INTO v_event_id, v_input_data_id
    FROM public.auto_campaign_zalo_realtime_group_events AS event
    WHERE event.campaign_id = p_campaign_id AND event.target_uid = v_target_uid;
    RETURN QUERY SELECT false, v_event_id, v_input_data_id;
    RETURN;
  END IF;

  INSERT INTO public.auto_campaign_input_data (
    campaign_id, input_id, name, uid, status, note, schedule
  ) VALUES (
    p_campaign_id, NULL, v_target_name, v_target_uid, 'chờ xử lý', '', v_schedule_at
  ) RETURNING id INTO v_input_data_id;

  UPDATE public.auto_campaign_zalo_realtime_group_events
  SET input_data_id = v_input_data_id, updated_at = now()
  WHERE id = v_event_id;
  UPDATE public.auto_campaigns
  SET schedule = v_schedule_at, updated_at = now()
  WHERE id = p_campaign_id AND account_id = p_account_id
    AND status IN ('chờ xử lý', 'đang chạy')
    AND (schedule IS NULL OR schedule < now() OR schedule > v_schedule_at);

  RETURN QUERY SELECT true, v_event_id, v_input_data_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_sms_auto_account_for_staff(p_staff_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_staff public.org_staff%ROWTYPE;
  v_phone text;
  v_primary_username text;
  v_fallback_username text;
  v_selected_username text;
  v_existing_account_id bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('auto_accounts_sms_username', 0));

  SELECT * INTO v_staff
  FROM public.org_staff
  WHERE id = p_staff_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_phone := btrim(coalesce(v_staff.phone, ''));
  IF v_phone = '' THEN
    RETURN NULL;
  END IF;

  SELECT id INTO v_existing_account_id
  FROM public.auto_accounts
  WHERE staff_id = v_staff.id
    AND flatform_type = 'sms'
    AND coalesce(is_delete, false) = false
  ORDER BY id
  LIMIT 1;

  IF v_existing_account_id IS NOT NULL THEN
    RETURN v_existing_account_id;
  END IF;

  v_primary_username := v_phone;
  v_fallback_username := v_staff.organization_id::text || '.' || v_phone;

  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_accounts
    WHERE flatform_type = 'sms'
      AND coalesce(is_delete, false) = false
      AND btrim(coalesce(username, '')) = v_primary_username
  ) THEN
    v_selected_username := v_primary_username;
  ELSIF NOT EXISTS (
    SELECT 1
    FROM public.auto_accounts
    WHERE flatform_type = 'sms'
      AND coalesce(is_delete, false) = false
      AND btrim(coalesce(username, '')) = v_fallback_username
  ) THEN
    v_selected_username := v_fallback_username;
  ELSE
    RAISE EXCEPTION 'Cannot create SMS account for staff %, username candidates already exist: %, %',
      v_staff.id, v_primary_username, v_fallback_username;
  END IF;

  INSERT INTO public.auto_accounts (
    name,
    flatform_type,
    login_status,
    status,
    is_active,
    is_delete,
    staff_id,
    organization_id,
    username,
    password,
    created_at,
    updated_at
  ) VALUES (
    v_phone,
    'sms',
    'chưa đăng nhập',
    'chờ xử lý',
    true,
    false,
    v_staff.id,
    v_staff.organization_id,
    v_selected_username,
    '123456',
    now(),
    now()
  )
  RETURNING id INTO v_existing_account_id;

  RETURN v_existing_account_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_alert_bug_stuck(p_hours numeric DEFAULT 2)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_link    text;
  rec       record;
  v_res     record;
  v_staff   text;
  v_shop    text;
  v_page    text;
  v_plink   text;
  v_payload jsonb;
  v_req     bigint;
  v_ins     uuid;
  v_sent    integer := 0;
  v_hour_vn integer := extract(hour from now() AT TIME ZONE 'Asia/Ho_Chi_Minh');
BEGIN
  IF (extract(hour from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int * 60 + extract(minute from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int) NOT BETWEEN 510 AND 1079 THEN RETURN 0; END IF; -- 8h30-18h VN
  SELECT link INTO v_link FROM aka_webhook_link WHERE id = 1;
  IF v_link IS NULL OR v_link = '' THEN RETURN 0; END IF;

  FOR rec IN
    SELECT m.id gom_id, m.conversation_id, m.contact_id, m.shop_id_2, m.contact_name,
           m.bot_intent, m.question_content, m.staff_id, m.created_at
    FROM message_gom m
    WHERE m.account_id = 1001
      AND m.bot_intent IN ('C3_REPORT_BUG','L1_TROUBLESHOOT')
      AND m.status = 'no_answer'
      AND m.created_at < now() - make_interval(hours => p_hours::int)
      AND m.created_at > now() - interval '6 hours'
      AND NOT EXISTS (SELECT 1 FROM aka_sales_alert_log l WHERE l.gom_id = m.id)
    ORDER BY m.created_at
    LIMIT 20
  LOOP
    SELECT * INTO v_res FROM fn_resolve_gom_staff(NULL, rec.staff_id, rec.contact_id, rec.shop_id_2);
    v_staff := NULL;
    IF v_res.o_org_staff_id IS NOT NULL THEN
      SELECT COALESCE(os.name_akabiz, os.name) INTO v_staff FROM org_staff os WHERE os.id = v_res.o_org_staff_id;
    END IF;
    IF v_staff IS NULL OR v_staff = '' THEN v_staff := 'Chưa gán NV'; END IF;

    SELECT s.name, s.pancake_page_id INTO v_shop, v_page FROM shops s WHERE s.id = rec.shop_id_2;
    v_plink := CASE WHEN v_page IS NOT NULL AND rec.conversation_id IS NOT NULL
               THEN 'https://pancake.vn/' || v_page || '?c_id=' || rec.conversation_id ELSE '' END;

    v_payload := jsonb_build_object(
      'alertReason',      'Khách đang KẸT LỖI, chưa ai theo sau ' || p_hours || ' giờ',
      'staffName',        v_staff,
      'assignedVia',      v_res.o_via,
      'customerName',     COALESCE(rec.contact_name,''),
      'intent',           rec.bot_intent,
      'customerQuestion', COALESCE(rec.question_content,''),
      'sentAt',           to_char(rec.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh','DD/MM HH24:MI'),
      'pancakeLink',      v_plink,
      'pancake_page',     COALESCE(v_shop,''),
      'note',             'Khách báo lỗi/đang xử lý lỗi mà không được phản hồi — rủi ro churn cao'
    );

    INSERT INTO aka_sales_alert_log(gom_id, intent_code, webhook_url, payload, alert_kind, conversation_id)
    VALUES (rec.gom_id, rec.bot_intent, v_link, v_payload, 'bug_stuck', rec.conversation_id)
    ON CONFLICT (gom_id) DO NOTHING
    RETURNING gom_id INTO v_ins;
    IF v_ins IS NULL THEN CONTINUE; END IF;

    SELECT net.http_post(url := v_link, body := v_payload,
      headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req;
    UPDATE aka_sales_alert_log SET net_request_id = v_req WHERE gom_id = v_ins;
    v_sent := v_sent + 1;
  END LOOP;
  RETURN v_sent;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_alert_stacked_unanswered(p_min integer DEFAULT 3, p_window_hours integer DEFAULT 4)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_link    text;
  rec       record;
  v_res     record;
  v_staff   text;
  v_shop    text;
  v_page    text;
  v_plink   text;
  v_payload jsonb;
  v_req     bigint;
  v_sent    integer := 0;
  v_ins     uuid;
  v_hour_vn integer := extract(hour from now() AT TIME ZONE 'Asia/Ho_Chi_Minh');
BEGIN
  IF (extract(hour from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int * 60 + extract(minute from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int) NOT BETWEEN 510 AND 1079 THEN RETURN 0; END IF; -- 8h30-18h VN

  SELECT link INTO v_link FROM aka_webhook_link WHERE id = 1;
  IF v_link IS NULL OR v_link = '' THEN RETURN 0; END IF;

  FOR rec IN
    SELECT m.conversation_id, m.contact_id, m.shop_id_2,
           max(m.contact_name) contact_name,
           count(*) cnt,
           (array_agg(m.id ORDER BY m.created_at DESC) FILTER (WHERE NOT EXISTS
             (SELECT 1 FROM aka_sales_alert_log l0 WHERE l0.gom_id = m.id)))[1] free_gom_id,
           max(m.staff_id::text)::uuid any_staff_id,
           string_agg(DISTINCT m.bot_intent, ', ') intents,
           jsonb_agg(left(coalesce(m.question_content,''),150) ORDER BY m.created_at) questions
    FROM message_gom m
    JOIN aka_ai_intent i ON i.intent_code = m.bot_intent AND i.is_active AND i.is_quan_trong
    WHERE m.account_id = 1001
      AND m.status = 'no_answer'
      AND m.conversation_id IS NOT NULL
      AND m.created_at > now() - make_interval(hours => p_window_hours)
    GROUP BY m.conversation_id, m.contact_id, m.shop_id_2
    HAVING count(*) >= p_min
    LIMIT 20
  LOOP
    IF rec.free_gom_id IS NULL THEN CONTINUE; END IF;

    IF EXISTS (SELECT 1 FROM aka_sales_alert_log l
               WHERE l.alert_kind = 'stacked' AND l.conversation_id = rec.conversation_id
                 AND (l.sent_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
                     = (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) THEN CONTINUE; END IF;

    SELECT * INTO v_res FROM fn_resolve_gom_staff(NULL, rec.any_staff_id, rec.contact_id, rec.shop_id_2);
    v_staff := NULL;
    IF v_res.o_org_staff_id IS NOT NULL THEN
      SELECT COALESCE(os.name_akabiz, os.name) INTO v_staff FROM org_staff os WHERE os.id = v_res.o_org_staff_id;
    END IF;
    IF v_staff IS NULL OR v_staff = '' THEN v_staff := 'Chưa gán NV'; END IF;

    SELECT s.name, s.pancake_page_id INTO v_shop, v_page FROM shops s WHERE s.id = rec.shop_id_2;
    v_plink := CASE WHEN v_page IS NOT NULL THEN 'https://pancake.vn/' || v_page || '?c_id=' || rec.conversation_id ELSE '' END;

    v_payload := jsonb_build_object(
      'alertReason',      'KHẨN: khách nhắn ' || rec.cnt || ' tin liên tiếp chưa ai trả lời (trong ' || p_window_hours || 'h)',
      'staffName',        v_staff,
      'assignedVia',      v_res.o_via,
      'customerName',     COALESCE(rec.contact_name,''),
      'messageCount',     rec.cnt,
      'intent',           rec.intents,
      'customerQuestion', (SELECT string_agg(q,' | ') FROM jsonb_array_elements_text(rec.questions) q),
      'pancakeLink',      v_plink,
      'pancake_page',     COALESCE(v_shop,''),
      'note',             'Khách đang chờ dồn nhiều tin — ưu tiên xử lý ngay'
    );

    INSERT INTO aka_sales_alert_log(gom_id, intent_code, webhook_url, payload, alert_kind, conversation_id)
    VALUES (rec.free_gom_id, 'STACKED', v_link, v_payload, 'stacked', rec.conversation_id)
    ON CONFLICT (gom_id) DO NOTHING
    RETURNING gom_id INTO v_ins;
    IF v_ins IS NULL THEN CONTINUE; END IF;

    SELECT net.http_post(url := v_link, body := v_payload,
      headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req;
    UPDATE aka_sales_alert_log SET net_request_id = v_req WHERE gom_id = v_ins;
    v_sent := v_sent + 1;
  END LOOP;
  RETURN v_sent;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_birthday_care_process_job_v2(p_job_id bigint, p_dry_run boolean DEFAULT false, p_allow_past boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job       aka_birthday_care_job%rowtype;
  v_cfg       aka_birthday_care_config%rowtype;
  v_gom       message_gom%rowtype;
  v_contact   contacts%rowtype;
  v_cust      aka_customer%rowtype;
  v_customer_id bigint;
  v_resolve_source text;
  v_phone     text;
  v_phone_from_name text;
  v_name      text;
  v_pancake_url text;
  v_lifecycle jsonb;
  v_owner_id  bigint; v_org_id bigint; v_owner_name text; v_owner_source text;
  v_existing_crm_id bigint; v_existing_type bigint;
  v_day_start timestamptz; v_day_end timestamptz;
  v_type_name text; v_priority integer;
  v_ctx jsonb; v_comp jsonb;
  v_source_type text;
  v_sel jsonb;
  v_crm_id bigint;
  v_last_msg text; v_last_msg_at timestamptz;
  v_result jsonb;
  v_now timestamptz := now();
begin
  select * into v_job from aka_birthday_care_job where id = p_job_id for update skip locked;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'job_not_found_or_locked', 'job_id', p_job_id);
  end if;
  if v_job.status <> 'queued' and not p_dry_run then
    return jsonb_build_object('ok', true, 'action', 'already_' || v_job.status, 'job_id', p_job_id, 'crm_id', v_job.crm_id);
  end if;

  select * into v_cfg from aka_birthday_care_config where singleton;
  select * into v_gom from message_gom where id = v_job.message_gom_id;
  if not found then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'gom_not_found', null, null);
  end if;
  if not fn_birthday_care_is_birthday_v2(v_gom.intent, v_gom.ai_intent, v_gom.bot_intent, v_gom.question_content) then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'not_birthday', null, null);
  end if;
  -- ưu đãi chỉ có hiệu lực đúng ngày sinh nhật: job của ngày cũ bỏ qua (trừ khi ép)
  if v_job.birthday_date_vn <> (v_now at time zone 'Asia/Ho_Chi_Minh')::date and not p_allow_past then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'birthday_day_expired', null, null);
  end if;
  if not coalesce(v_cfg.enabled, false) then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'flow_disabled', null, null);
  end if;

  if v_gom.contact_id is not null then
    select * into v_contact from contacts where id = v_gom.contact_id;
    if found and coalesce(v_contact.is_group, false) then
      return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'group_contact', null, null);
    end if;
  end if;

  -- ===== SĐT: contact → gom → trích từ tên hiển thị =====
  v_phone_from_name := (regexp_match(coalesce(v_contact.name, '') || ' ' || coalesce(v_gom.contact_name, ''), '(0[1-9][0-9]{8})'))[1];
  v_phone := normalize_phone(coalesce(nullif(btrim(v_contact.phone), ''), nullif(btrim(v_gom.phone), ''), nullif(btrim(v_gom.shared_phone), ''), v_phone_from_name));
  if v_phone !~ '^0[1-9][0-9]{8}$' then v_phone := null; end if;

  v_pancake_url := coalesce(fn_zalo_chat_referral_pancake_url_v1(v_gom.id),
    (select 'https://pancake.vn/' || s.pancake_page_id || '?c_id=' || v_gom.conversation_id
       from shops s where s.id::text = v_gom.shop_id and nullif(btrim(s.pancake_page_id), '') is not null limit 1));

  -- ===== resolve khách =====
  v_customer_id := v_gom.aka_customer_id; v_resolve_source := 'message_gom';
  if v_customer_id is null and v_contact.customer_id is not null then
    v_customer_id := v_contact.customer_id; v_resolve_source := 'contact';
  end if;
  if v_customer_id is not null then
    select * into v_cust from aka_customer where id = v_customer_id;
    if not found then
      v_customer_id := null;
    elsif coalesce(v_cust.record_state, 'active') = 'merged' and v_cust.merged_into_customer_id is not null then
      v_customer_id := v_cust.merged_into_customer_id; v_resolve_source := v_resolve_source || '+merged';
      select * into v_cust from aka_customer where id = v_customer_id;
    end if;
  end if;
  if v_customer_id is null and v_phone is not null then
    select * into v_cust from aka_customer c
    where normalize_phone(c.phone) = v_phone and coalesce(c.record_state, 'active') <> 'merged'
    order by case when c.account_id = v_gom.account_id then 0 else 1 end, c.created_at desc nulls last, c.id desc
    limit 1;
    if found then v_customer_id := v_cust.id; v_resolve_source := case when v_phone_from_name is not null and v_phone = normalize_phone(v_phone_from_name) then 'phone_in_name' else 'phone' end; end if;
  end if;

  v_name := coalesce(
    fn_birthday_care_clean_name_v2(v_cust.name),
    fn_birthday_care_clean_name_v2(v_contact.name),
    fn_birthday_care_clean_name_v2(v_gom.contact_name),
    nullif(btrim(v_cust.name_zalo), ''));
  v_phone := coalesce(nullif(normalize_phone(v_cust.phone), ''), v_phone);

  if v_customer_id is null then
    update aka_birthday_care_job set contact_name = coalesce(v_name, contact_name), phone = v_phone, pancake_url = v_pancake_url, updated_at = v_now where id = p_job_id;
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'customer_unresolved', null, null);
  end if;

  -- ===== phân loại gói =====
  v_lifecycle := fn_birthday_care_classify_v2(v_customer_id, v_job.birthday_date_vn);
  update aka_birthday_care_job
    set customer_id = v_customer_id, customer_name = v_name, phone = v_phone, pancake_url = v_pancake_url,
        resolve_source = v_resolve_source, lifecycle = v_lifecycle, updated_at = v_now
  where id = p_job_id;

  if not coalesce((v_lifecycle ->> 'eligible')::boolean, false) then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', coalesce(v_lifecycle ->> 'skip_reason', 'not_eligible'), null, null);
  end if;
  v_sel := v_lifecycle -> 'selected';

  -- ===== chống trùng =====
  v_source_type := 'birthday_care:' || v_gom.id::text;
  select id into v_existing_crm_id from aka_crm where source_type = v_source_type limit 1;
  if v_existing_crm_id is not null then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'duplicate', 'duplicate_source', v_existing_crm_id, v_existing_crm_id);
  end if;
  v_day_start := (v_job.birthday_date_vn::timestamp) at time zone 'Asia/Ho_Chi_Minh';
  v_day_end := v_day_start + interval '1 day';
  perform pg_advisory_xact_lock(hashtextextended('birthday_care:' || v_customer_id::text || ':' || v_job.birthday_date_vn::text, 0));
  select c.id, c.crm_type_id into v_existing_crm_id, v_existing_type
  from aka_crm c
  where c.customer_id = v_customer_id and c.created_at >= v_day_start and c.created_at < v_day_end
    and (c.crm_type_id = v_cfg.crm_type_id or coalesce(v_cfg.skip_if_other_crm_today, true))
  order by case when c.crm_type_id = v_cfg.crm_type_id then 0 else 1 end, c.created_at desc
  limit 1;
  if v_existing_crm_id is not null then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'duplicate',
      case when v_existing_type = v_cfg.crm_type_id then 'duplicate_customer_birthday' else 'customer_has_crm_today_type_' || v_existing_type end,
      null, v_existing_crm_id);
  end if;

  -- ===== owner (cùng thang với phone-nudge / referral v3) =====
  select os.id, os.organization_id, os.name, 'chủ khách' into v_owner_id, v_org_id, v_owner_name, v_owner_source
  from org_staff os where os.id = v_cust.org_staff_id_owner and os.is_active = true;
  if v_owner_id is null and v_gom.conversation_id is not null then
    select os.id, os.organization_id, os.name, 'NV trả lời hội thoại' into v_owner_id, v_org_id, v_owner_name, v_owner_source
    from message_gom g2 join org_staff os on os.id = g2.answer_org_staff_id
    where g2.conversation_id = v_gom.conversation_id and g2.shop_id is not distinct from v_gom.shop_id
      and g2.answer_org_staff_id is not null and os.is_active = true
    order by coalesce(g2.answer_first_at, g2.created_at) desc limit 1;
  end if;
  if v_owner_id is null and v_contact.id is not null then
    select os.id, os.organization_id, os.name, 'NV phụ trách contact' into v_owner_id, v_org_id, v_owner_name, v_owner_source
    from unnest(coalesce(v_contact.staff_ids, array[]::text[])) sid(value)
    join org_staff os on os.chat_staff_id::text = sid.value
    where os.is_active = true order by os.id limit 1;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id, os.name, 'quản lý page' into v_owner_id, v_org_id, v_owner_name, v_owner_source
    from shops s join org_staff os on os.id = s.manager_org_staff_id
    where os.is_active = true and s.id = v_gom.shop_id_2 limit 1;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id, os.name, 'chia tự động' into v_owner_id, v_org_id, v_owner_name, v_owner_source
    from org_staff os
    where os.is_active = true and os.is_data_division = true
    order by (select count(*) from aka_crm x where x.org_staff_owner_id = os.id and x.created_at >= v_day_start), os.id
    limit 1;
  end if;
  if v_owner_id is null or v_org_id is null then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'error', 'active_owner_not_resolved', null, null);
  end if;

  -- ===== tin gần nhất của khách (ngoài tin sinh nhật) =====
  select g2.question_content, coalesce(g2.question_first_at, g2.created_at) into v_last_msg, v_last_msg_at
  from message_gom g2
  where g2.conversation_id = v_gom.conversation_id and g2.id <> v_gom.id and g2.initiated_by = 'CUSTOMER'
    and nullif(btrim(g2.question_content), '') is not null
    and not fn_birthday_care_is_birthday_v2(g2.intent, g2.ai_intent, g2.bot_intent, g2.question_content)
  order by coalesce(g2.question_first_at, g2.created_at) desc limit 1;

  select t.name, t.stt into v_type_name, v_priority from aka_crm_type t where t.id = v_cfg.crm_type_id and t.is_active = true;
  if not found then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'error', 'crm_type_inactive', null, null);
  end if;

  v_ctx := jsonb_build_object(
    'name', v_name, 'phone', v_phone, 'zalo', nullif(btrim(v_cust.zalo), ''), 'pancake_url', v_pancake_url,
    'birthday_date_vn', v_job.birthday_date_vn,
    'greeting_sent_at', v_gom.sent_at, 'greeting_status', v_gom.send_status, 'greeting_content', v_gom.reply_content,
    'lifecycle', v_lifecycle, 'owner_name', v_owner_name, 'owner_source', v_owner_source,
    'last_customer_message', v_last_msg, 'last_customer_message_at', v_last_msg_at,
    'cfg', to_jsonb(v_cfg));
  v_comp := fn_birthday_care_compose_v2(v_ctx);

  if p_dry_run then
    return jsonb_build_object('ok', true, 'dry_run', true, 'action', 'would_create', 'job_id', p_job_id,
      'customer_id', v_customer_id, 'customer_name', v_name, 'phone', v_phone, 'pancake_url', v_pancake_url,
      'resolve_source', v_resolve_source, 'rule', v_lifecycle ->> 'rule', 'segment', v_lifecycle ->> 'segment',
      'owner', v_owner_name, 'owner_source', v_owner_source, 'note', v_comp ->> 'note', 'message', v_comp ->> 'message');
  end if;

  insert into aka_crm (
    customer_id, customer_name, customer_phone, crm_type_id, priority, org_staff_owner_id, organization_id,
    created_by, note, suggested_content, proposed_content, proposed_channel, suggested_channel_id,
    cskh_due_date, is_read, source_type, source_order_id, org_organization_product_id,
    source_expiration_date, source_expiration_source, sql_account_id,
    gen_agent, gen_status, gen_at, gen_meta, pancake_url
  ) values (
    v_customer_id, v_name, v_phone, v_cfg.crm_type_id, v_priority, v_owner_id, v_org_id,
    v_owner_id, v_comp ->> 'note', v_comp ->> 'message', v_comp ->> 'message', 'zalo', 8,
    private.zalo_referral_due_date_v1(v_now), false, v_source_type,
    case when v_sel ->> 'source' = 'aka_order' then (v_sel ->> 'id')::bigint end,
    case when v_sel ->> 'source' = 'org_organization_product' then (v_sel ->> 'id')::bigint end,
    (v_sel ->> 'expires_on')::date,
    case when v_sel ->> 'expires_on' is not null then 'birthday_care_v2:' || (v_sel ->> 'source') end,
    v_gom.account_id,
    'birthday-care-v2', 'created', v_now,
    jsonb_strip_nulls(jsonb_build_object(
      'version', 'v2', 'job_id', p_job_id, 'message_gom_id', v_gom.id::text, 'conversation_id', v_gom.conversation_id,
      'contact_id', v_gom.contact_id::text, 'birthday_date_vn', v_job.birthday_date_vn, 'resolve_source', v_resolve_source,
      'rule', v_lifecycle ->> 'rule', 'segment', v_lifecycle ->> 'segment', 'selected', v_sel,
      'stats', v_lifecycle -> 'stats', 'offer', v_comp ->> 'offer', 'bonus_days', v_comp -> 'bonus_days',
      'discount_percent', v_comp -> 'discount_percent', 'owner_source', v_owner_source)),
    v_pancake_url
  ) returning id into v_crm_id;

  update message_gom set crm_id = coalesce(crm_id, v_crm_id), crm_ids = array_append(coalesce(crm_ids, '{}'::bigint[]), v_crm_id)
  where id = v_gom.id and not (v_crm_id = any (coalesce(crm_ids, '{}'::bigint[])));

  v_result := fn_birthday_care_finish_v2(p_job_id, false, 'created', v_lifecycle ->> 'rule', v_crm_id, null);
  return v_result || jsonb_build_object('customer_id', v_customer_id, 'customer_name', v_name, 'owner', v_owner_name, 'segment', v_lifecycle ->> 'segment');
exception
  when others then
    update aka_birthday_care_job
      set attempt_count = attempt_count + 1, last_error = left(sqlstate || ' ' || sqlerrm, 500), updated_at = now(),
          status = case when attempt_count + 1 >= coalesce(v_cfg.max_attempts, 3) then 'error' else 'queued' end,
          reason = case when attempt_count + 1 >= coalesce(v_cfg.max_attempts, 3) then 'max_attempts' else reason end,
          process_after = now() + interval '5 minutes'
    where id = p_job_id;
    return jsonb_build_object('ok', false, 'error', sqlstate || ' ' || sqlerrm, 'job_id', p_job_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_chat_followup_post_ai_filter_v1(p_day date, p_customer_id bigint, p_contact_id uuid, p_conversation_id text, p_gom_id uuid, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  cfg             public.aka_chat_followup_filter_config%rowtype;
  v_final         bigint := p_customer_id;
  v_phone         text;
  v_phone_src     text;
  v_pancake       text;
  v_conv          text;
  v_page          text;
  v_owner         bigint;
  v_owner_src     text;
  v_group         text;
  v_days_left     integer;
  v_reason        text := 'ok';
  v_pass          boolean := true;
  v_target        bigint;
  v_merged        boolean := false;
  v_merge_err     text;
  v_cust          public.aka_customer%rowtype;
  v_dup_crm       bigint;
  v_dau           timestamptz;
  v_cuoi          timestamptz;
  v_now           timestamptz := now();
  v_paid_far      boolean;
  v_paid_near     boolean;
  v_paid_near_exp timestamptz;
  v_had_paid      boolean;
  v_demo_active   boolean;
  v_had_demo      boolean;
  v_details       jsonb := '{}'::jsonb;
begin
  select * into cfg from public.aka_chat_followup_filter_config where id = 1;
  if cfg.id is null or not cfg.enabled then
    return jsonb_build_object('passed', true, 'reason', 'filter_disabled',
                              'final_customer_id', p_customer_id);
  end if;

  v_dau  := ((p_day - cfg.crm_dup_window_days)::timestamp at time zone 'Asia/Ho_Chi_Minh');
  v_cuoi := ((p_day + cfg.crm_dup_window_days + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh');

  -- ---------- A. SDT ----------
  select e.phone, e.source into v_phone, v_phone_src
    from public.fn_chat_followup_extract_phone_v1(p_customer_id, p_contact_id, p_conversation_id, p_gom_id) e
   limit 1;

  -- ---------- B. Link pancake dung chuan ----------
  if p_contact_id is not null then
    select ct.conversion_id, sh.pancake_page_id
      into v_conv, v_page
      from public.contacts ct
      left join public.shops sh on sh.id::text = ct.shop_id
     where ct.id = p_contact_id;
    if v_conv is not null and v_page is not null then
      v_pancake := format('https://pancake.vn/%s?c_id=%s', v_page, v_conv);
      if v_pancake !~ '^https://pancake\.vn/[A-Za-z0-9_\-]+\?c_id=[A-Za-z0-9_\-]+$' then
        v_pancake := null;
      end if;
    end if;
  end if;

  -- ---------- C. Gop trung theo SDT ----------
  if v_phone is not null then
    select c.id into v_target
      from public.aka_customer c
     where public.normalize_phone(c.phone) = v_phone
       and coalesce(c.record_state, '') <> 'merged'
     order by (c.id = p_customer_id) desc, c.id desc
     limit 1;
    if v_target is not null and v_target <> p_customer_id then
      v_final := v_target;
      v_details := v_details || jsonb_build_object('phone_matched_customer_id', v_target);
    end if;
  end if;

  select * into v_cust from public.aka_customer where id = v_final;
  if v_cust.id is null then
    return jsonb_build_object('passed', false, 'reason', 'khach_khong_ton_tai', 'final_customer_id', v_final);
  end if;
  if coalesce(v_cust.record_state,'') = 'merged' and v_cust.merged_into_customer_id is not null then
    v_final := v_cust.merged_into_customer_id;
    select * into v_cust from public.aka_customer where id = v_final;
  end if;

  -- ---------- D. Nhom khach (tinh tren khach cuoi cung) ----------
  select
    bool_or(exp_at > v_now + make_interval(days => cfg.renewal_window_days)),
    bool_or(exp_at >= v_now and exp_at <= v_now + make_interval(days => cfg.renewal_window_days)),
    max(exp_at) filter (where exp_at >= v_now and exp_at <= v_now + make_interval(days => cfg.renewal_window_days)),
    count(*) > 0
  into v_paid_far, v_paid_near, v_paid_near_exp, v_had_paid
  from (
    select ao.date_expiration as exp_at
      from public.aka_order ao
     where ao.customer_id = v_final
       and coalesce(ao.is_active, true) = true
       and coalesce(ao.is_demo, false) = false
       and lower(coalesce(ao.package, '')) <> 'demo'
       and nullif(btrim(coalesce(ao.product_list, '')), '') is not null
       and btrim(coalesce(ao.product_list, '')) <> '[]'
    union all
    select op.expiration_date
      from public.org_organization_product op
      join public.org_organization org on org.id = op.organization_id
     where org.customer_id = v_final
       and coalesce(op.is_deleted, false) = false
       and op.is_paid
       and coalesce(op.is_lock, false) = false
  ) paid;

  select bool_or(exp_at >= v_now), count(*) > 0
    into v_demo_active, v_had_demo
  from (
    select ao.date_expiration as exp_at
      from public.aka_order ao
     where ao.customer_id = v_final
       and (coalesce(ao.is_demo, false) or lower(coalesce(ao.package, '')) = 'demo')
    union all
    select op.expiration_date
      from public.org_organization_product op
      join public.org_organization org on org.id = op.organization_id
     where org.customer_id = v_final
       and coalesce(op.is_deleted, false) = false
       and not coalesce(op.is_paid, false)
  ) demo;

  v_paid_far := coalesce(v_paid_far, false);
  v_paid_near := coalesce(v_paid_near, false);
  v_had_paid := coalesce(v_had_paid, false);
  v_demo_active := coalesce(v_demo_active, false);
  v_had_demo := coalesce(v_had_demo, false);

  if v_paid_far then
    v_group := 'con_han_dai'; v_pass := false; v_reason := 'con_han_dai';
  elsif v_paid_near then
    v_group := 'con_han_sap_het';
    v_days_left := greatest(0, floor(extract(epoch from (v_paid_near_exp - v_now)) / 86400))::int;
  elsif v_had_paid then
    v_group := 'het_han_su_dung';
  elsif v_demo_active and not cfg.allow_active_demo then
    v_group := 'dang_demo'; v_pass := false; v_reason := 'dang_demo';
  elsif v_had_demo then
    v_group := case when v_demo_active then 'dang_demo' else 'het_han_demo' end;
  else
    v_group := 'chua_mua';
  end if;

  -- ---------- E. Phai co SDT hoac link pancake ----------
  if v_pass and cfg.require_contact and v_phone is null and v_pancake is null then
    v_pass := false; v_reason := 'khong_co_lien_he';
  end if;

  -- ---------- F. Chong trung CRM ±N ngay, moi type ----------
  if v_pass then
    select cr.id into v_dup_crm
      from public.aka_crm cr
     where cr.customer_id = v_final
       and coalesce(cr.source_type, '') not like 'chat_followup:' || to_char(p_day, 'YYYYMMDD') || ':%'
       and (
         (cr.created_at >= v_dau and cr.created_at < v_cuoi)
         or (cr.cskh_due_date >= v_dau and cr.cskh_due_date < v_cuoi)
       )
     order by cr.created_at desc
     limit 1;
    if v_dup_crm is not null then
      v_pass := false; v_reason := 'trung_crm_7_ngay';
      v_details := v_details || jsonb_build_object('dup_crm_id', v_dup_crm);
    end if;
  end if;

  -- ---------- G. Owner = NV nhan tin gan nhat ----------
  select g.answer_org_staff_id into v_owner
    from public.message_gom g
   where ((p_conversation_id is not null and g.conversation_id = p_conversation_id) or g.id = p_gom_id)
     and g.answer_org_staff_id is not null
   order by coalesce(g.answer_last_at, g.created_at) desc
   limit 1;
  v_owner_src := 'conversation';
  if v_owner is null and p_contact_id is not null then
    select g.answer_org_staff_id into v_owner
      from public.message_gom g
     where g.contact_id = p_contact_id and g.answer_org_staff_id is not null
     order by coalesce(g.answer_last_at, g.created_at) desc
     limit 1;
    v_owner_src := 'contact';
  end if;
  if v_owner is null then
    v_owner := v_cust.org_staff_id_owner; v_owner_src := 'customer_owner';
  end if;
  if v_owner is null then
    select s.id into v_owner
      from public.org_staff s
     where s.is_active and s.is_data_division
     order by (select count(*) from public.aka_crm r2
                where r2.org_staff_owner_id = s.id and r2.cskh_completed_date is null), s.id
     limit 1;
    v_owner_src := 'data_division_least_loaded';
  end if;

  -- ---------- H. Ap dung ----------
  if p_apply and v_pass and cfg.update_customer then
    update public.aka_customer c
       set phone = case when public.fn_normalize_phone_vn(c.phone) ~ '^0[35789][0-9]{8}$' then c.phone else coalesce(v_phone, c.phone) end,
           custom_fields = coalesce(c.custom_fields, '{}'::jsonb)
             || case when v_pancake is not null then jsonb_build_object(
                  'pancake_url', v_pancake,
                  'contact_id', p_contact_id::text,
                  'conversion_id', v_conv,
                  'pancake_page_id', v_page) else '{}'::jsonb end
             || jsonb_build_object('chat_followup_filter_at', v_now, 'chat_followup_group', v_group),
           org_staff_id_owner = case when cfg.set_customer_owner_if_null then coalesce(c.org_staff_id_owner, v_owner) else c.org_staff_id_owner end,
           updated_at = v_now
     where c.id = v_final;

    if p_contact_id is not null then
      update public.contacts ct set customer_id = v_final
       where ct.id = p_contact_id and ct.customer_id is distinct from v_final;
    end if;

    if v_final <> p_customer_id and cfg.merge_shell_customer then
      if exists (
        select 1 from public.aka_customer s
         where s.id = p_customer_id
           and coalesce(s.record_state,'') <> 'merged'
           and coalesce(s.custom_fields->>'nguon','') like 'chat-followup%'
           and nullif(btrim(coalesce(s.phone,'')), '') is null
           and not exists (select 1 from public.aka_order o where o.customer_id = s.id)
           and not exists (select 1 from public.org_organization og where og.customer_id = s.id)
      ) then
        begin
          perform public.fn_merge_verified_customer_identity_v1(
            p_customer_id, v_final, null, null, 'chat-followup-v2: trung SDT ' || v_phone);
          v_merged := true;
        exception when others then
          v_merge_err := sqlerrm;
        end;
      end if;
    end if;
  end if;

  v_details := v_details || jsonb_build_object(
    'paid_far', v_paid_far, 'paid_near', v_paid_near, 'had_paid', v_had_paid,
    'demo_active', v_demo_active, 'had_demo', v_had_demo,
    'owner_source', v_owner_src, 'merged_shell', v_merged, 'merge_error', v_merge_err);

  insert into public.aka_chat_followup_filter_log
    (day, mode, customer_id, final_customer_id, gom_id, contact_id, passed, reason,
     customer_group, days_left, phone, phone_source, pancake_url, owner_id, details)
  values
    (p_day, case when p_apply then 'apply' else 'dry' end, p_customer_id, v_final, p_gom_id, p_contact_id,
     v_pass, v_reason, v_group, v_days_left, v_phone, v_phone_src, v_pancake, v_owner, v_details);

  return jsonb_build_object(
    'passed', v_pass,
    'reason', v_reason,
    'final_customer_id', v_final,
    'customer_group', v_group,
    'group_label', case v_group
                     when 'chua_mua' then 'Chua mua'
                     when 'het_han_demo' then 'Het han demo'
                     when 'het_han_su_dung' then 'Het han su dung'
                     when 'con_han_sap_het' then format('Con han - con %s ngay', v_days_left)
                     when 'dang_demo' then 'Dang demo'
                     else v_group end,
    'days_left', v_days_left,
    'phone', v_phone,
    'phone_source', v_phone_src,
    'pancake_url', v_pancake,
    'owner_id', v_owner,
    'owner_source', v_owner_src,
    'customer_name', v_cust.name,
    'details', v_details
  );
end
$function$

CREATE OR REPLACE FUNCTION public.fn_contact_match_aka_customer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id   integer;
  v_staff_id     text;
  v_org_staff_id bigint;
  v_page_id      text;
  v_up           jsonb;
  v_kcd_matches bigint[];
  v_kcd_url text;
BEGIN
  -- Personal Zalo akaBiz: match a unique full page+conversation identity, never create from phone hints.
  SELECT account_id,pancake_page_id INTO v_account_id,v_page_id
    FROM public.shops WHERE id::text=NEW.shop_id OR pancake_page_id=NEW.shop_id LIMIT 1;
  IF v_account_id=1001 AND v_page_id ~ '^pzl_[0-9]+$' AND NOT coalesce(NEW.is_group,false) THEN
    IF NEW.customer_id IS NULL AND NEW.conversion_id ~ '^pzl_u_[0-9]+_[0-9]+$' THEN
      v_kcd_url:='https://pancake.vn/'||v_page_id||'?c_id='||NEW.conversion_id;
      SELECT array_agg(DISTINCT coalesce(a.merged_into_customer_id,a.id)) INTO v_kcd_matches
      FROM public.aka_customer a WHERE a.account_id=1001 AND
        (a.pancake_url=v_kcd_url OR a.custom_fields->'pancake_urls' ? v_kcd_url);
      IF cardinality(v_kcd_matches)=1 THEN NEW.customer_id:=v_kcd_matches[1]; END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.phone IS NULL OR NEW.phone = '' THEN RETURN NEW; END IF;
  IF NEW.customer_id IS NOT NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.phone IS NOT DISTINCT FROM NEW.phone THEN RETURN NEW; END IF;

  SELECT account_id, pancake_page_id INTO v_account_id, v_page_id
  FROM public.shops WHERE pancake_page_id = NEW.shop_id OR id::text = NEW.shop_id LIMIT 1;
  IF v_account_id IS NULL OR v_account_id != 1001 THEN RETURN NEW; END IF;

  v_staff_id := CASE WHEN NEW.staff_ids IS NOT NULL AND array_length(NEW.staff_ids, 1) >= 1 THEN NEW.staff_ids[1]::text ELSE NULL END;
  IF v_staff_id IS NOT NULL THEN
    SELECT id INTO v_org_staff_id FROM public.org_staff WHERE chat_staff_id::text = v_staff_id AND is_active IS TRUE ORDER BY id LIMIT 1;
  END IF;

  -- (HÀM CHUNG) v2: gọi trực tiếp fn_upsert_aka_customer_v1 thay cho pg_net -> edge insert_aka_customer (đồng bộ, hết race, gắn ngay customer_id)
  BEGIN
    v_up := public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
      'phone', NEW.phone,
      'zalo_uid', NEW.uid,
      'pancake_url', CASE WHEN nullif(btrim(v_page_id), '') IS NOT NULL AND nullif(btrim(NEW.conversion_id), '') IS NOT NULL
                          AND coalesce(NEW.is_group, false) = false
                          THEN 'https://pancake.vn/' || v_page_id || '?c_id=' || NEW.conversion_id END,
      'name', COALESCE(NEW.name, NEW.zalo_name), 'name_zalo', NEW.zalo_name,
      'account_id', v_account_id, 'channel', 'trigger_from_contact', 'is_split_exempt', true,
      'org_staff_id', v_org_staff_id, 'chat_staff_id', v_staff_id,
      'creation_path', 'trigger_from_contact',
      'custom_fields', jsonb_build_object('contact_id', NEW.id::text, 'shop_id', NEW.shop_id)
    )));
    IF coalesce((v_up ->> 'ok')::boolean, false) THEN
      NEW.customer_id := (v_up ->> 'customer_id')::bigint;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_contact_match_aka_customer upsert failed for contact %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_escalate_repeat_offenders(p_min integer DEFAULT 3)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wid     bigint;
  v_link    text;
  v_is_live boolean;
  v_today   date := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  rec       record;
  v_payload jsonb;
  v_req     bigint;
  v_sent    integer := 0;
BEGIN
  SELECT id, link, is_live INTO v_wid, v_link, v_is_live
  FROM aka_webhook_link WHERE description LIKE 'ESCALATE QUAN LY%' ORDER BY id DESC LIMIT 1;
  IF v_link IS NULL OR v_link = '' THEN RETURN 0; END IF;

  FOR rec IN
    SELECT a.answer_org_staff_id staff_id,
           max(a.answer_staff_name) staff_name,
           count(*) cnt,
           string_agg(DISTINCT a.intent_code, ', ') intents,
           jsonb_agg(jsonb_build_object(
             'time', to_char(a.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh','HH24:MI'),
             'intent', a.intent_code,
             'score', a.relevance_score,
             'reason', (SELECT string_agg(b->>'name',', ') FROM jsonb_array_elements(a.reasons) b),
             'link', a.payload->>'pancakeLink') ORDER BY a.created_at) details
    FROM aka_answer_quality_alert a
    WHERE a.answer_org_staff_id IS NOT NULL
      AND a.status IN ('sent','dry_run')
      AND (a.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = v_today
    GROUP BY a.answer_org_staff_id
    HAVING count(*) >= p_min
  LOOP
    IF EXISTS (SELECT 1 FROM aka_staff_escalation_log l
               WHERE l.org_staff_id = rec.staff_id AND l.alert_date = v_today
                 AND l.alert_webhook_id = v_wid) THEN CONTINUE; END IF;

    v_payload := jsonb_build_object(
      'alertReason',  'NV tái phạm: nhiều cảnh báo chất lượng trong ngày',
      'staffName',    COALESCE(rec.staff_name,''),
      'alertCount',   rec.cnt,
      'date',         to_char(v_today,'DD/MM/YYYY'),
      'intents',      rec.intents,
      'details',      rec.details,
      'note',         'Tổng hợp từ ' || rec.cnt || ' cảnh báo chất lượng/thái độ trong ngày, đề nghị quản lý trao đổi trực tiếp với NV'
    );

    IF v_is_live THEN
      SELECT net.http_post(url := v_link, body := v_payload,
        headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req;
      INSERT INTO aka_staff_escalation_log(org_staff_id, alert_date, alert_count, breach_summary,
        alert_webhook_id, payload, net_request_id, status)
      VALUES (rec.staff_id, v_today, rec.cnt, rec.intents, v_wid, v_payload, v_req, 'sent')
      ON CONFLICT DO NOTHING;
    ELSE
      INSERT INTO aka_staff_escalation_log(org_staff_id, alert_date, alert_count, breach_summary,
        alert_webhook_id, payload, net_request_id, status)
      VALUES (rec.staff_id, v_today, rec.cnt, rec.intents, v_wid, v_payload, NULL, 'dry_run')
      ON CONFLICT DO NOTHING;
    END IF;
    v_sent := v_sent + 1;
  END LOOP;

  RETURN v_sent;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notify_answer_quality()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_intent   public.aka_ai_intent%ROWTYPE;
  v_breaches jsonb := '[]'::jsonb;
  v_val      numeric;
  r          record;
  v_state    record;
  v_wid      bigint;
  v_link     text;
  v_is_live  boolean;
  v_cap      integer;
  v_cnt      integer;
  v_shop     text;
  v_page     text;
  v_pancake  text;
  v_staff    text;
  v_res      record;
  v_staff_id bigint;
  v_sub      jsonb;
  v_summary  text;
  v_payload  jsonb;
  v_req      bigint;
  v_win_start time;
  v_win_end   time;
  v_win_dow   smallint[];
  v_local     timestamp;
  v_cta_name  text;
BEGIN
  SELECT * INTO v_intent FROM public.aka_ai_intent
   WHERE intent_code = NEW.bot_intent AND is_active LIMIT 1;
  IF NOT FOUND OR COALESCE(v_intent.is_notify_quality, false) = false THEN RETURN NULL; END IF;

  FOR r IN SELECT criterion_code, criterion_name, poor_threshold, alert_webhook_id, apply_intent_codes
           FROM public.aka_chat_quality_criteria
           WHERE is_send_alert AND alert_webhook_id IS NOT NULL AND poor_threshold IS NOT NULL
  LOOP
    IF r.apply_intent_codes IS NOT NULL AND NOT (NEW.bot_intent = ANY(r.apply_intent_codes)) THEN
      CONTINUE;
    END IF;
    -- Nhánh CTA: có phân loại AI thì dùng phân loại, KHÔNG so ngưỡng điểm nữa
    IF r.criterion_code = 'cta_conversion' AND NEW.cta_review IS NOT NULL THEN
      IF COALESCE((NEW.cta_review->>'can_thiet')::boolean, false)
         AND NEW.cta_review->>'loi' IN ('thieu','yeu','sai_giai_doan','lech_chu_de') THEN
        v_breaches := v_breaches || jsonb_build_object(
          'type','cta','code','cta_conversion',
          'name', CASE NEW.cta_review->>'loi'
                    WHEN 'thieu' THEN 'Thiếu CTA'
                    WHEN 'yeu' THEN 'CTA yếu'
                    WHEN 'sai_giai_doan' THEN 'CTA sai giai đoạn'
                    ELSE 'CTA lệch chủ đề' END,
          'loi', NEW.cta_review->>'loi',
          'value', NULLIF(NEW.relevance_breakdown->>'cta_conversion','')::numeric,
          'threshold', r.poor_threshold,
          'webhook_id', r.alert_webhook_id);
      END IF;
      CONTINUE;
    END IF;
    IF r.criterion_code = 'overall' THEN v_val := NEW.relevance_score;
    ELSE v_val := NULLIF(NEW.relevance_breakdown->>r.criterion_code, '')::numeric; END IF;
    IF v_val IS NOT NULL AND v_val < r.poor_threshold THEN
      v_breaches := v_breaches || jsonb_build_object('type','quality','code',r.criterion_code,
        'name',r.criterion_name,'value',v_val,'threshold',r.poor_threshold,'webhook_id',r.alert_webhook_id);
    END IF;
  END LOOP;

  SELECT s.state_code, s.state_name, s.alert_webhook_id, s.min_confidence INTO v_state
  FROM public.aka_staff_attitude_state s
  WHERE s.state_code = NEW.attitude_state_code AND s.is_send_alert AND s.alert_webhook_id IS NOT NULL;
  IF FOUND AND COALESCE(NEW.attitude_confidence,1) >= COALESCE(v_state.min_confidence,0.6) THEN
    v_breaches := v_breaches || jsonb_build_object('type','attitude','code',v_state.state_code,
      'name',v_state.state_name,'confidence',NEW.attitude_confidence,'webhook_id',v_state.alert_webhook_id);
  END IF;

  IF jsonb_array_length(v_breaches) = 0 THEN RETURN NULL; END IF;

  SELECT * INTO v_res FROM public.fn_resolve_gom_staff(NEW.answer_org_staff_id, NEW.staff_id, NEW.contact_id, NEW.shop_id_2);
  v_staff_id := v_res.o_org_staff_id;

  SELECT name, pancake_page_id INTO v_shop, v_page FROM public.shops WHERE id = NEW.shop_id_2;
  v_pancake := CASE WHEN v_page IS NOT NULL AND NEW.conversation_id IS NOT NULL
                    THEN 'https://pancake.vn/' || v_page || '?c_id=' || NEW.conversation_id ELSE '' END;

  IF v_staff_id IS NOT NULL THEN
    SELECT COALESCE(os.name_akabiz, os.name) INTO v_staff
    FROM public.org_staff os WHERE os.id = v_staff_id LIMIT 1;
  END IF;
  IF v_staff IS NULL OR v_staff = '' THEN v_staff := NULLIF(NEW.answer_staff_name, ''); END IF;
  IF v_staff IS NULL OR v_staff = '' THEN v_staff := 'Chưa gán NV'; END IF;

  FOR v_wid IN SELECT DISTINCT (b->>'webhook_id')::bigint FROM jsonb_array_elements(v_breaches) b
  LOOP
    IF EXISTS (SELECT 1 FROM public.aka_answer_quality_alert a
               WHERE a.gom_id = NEW.id AND a.alert_webhook_id = v_wid) THEN CONTINUE; END IF;

    SELECT link, is_live, max_per_staff_per_day, send_window_start, send_window_end, send_window_dow
      INTO v_link, v_is_live, v_cap, v_win_start, v_win_end, v_win_dow
    FROM public.aka_webhook_link WHERE id = v_wid;
    IF v_link IS NULL OR v_link = '' THEN CONTINUE; END IF;

    v_sub := (SELECT jsonb_agg(b) FROM jsonb_array_elements(v_breaches) b
              WHERE (b->>'webhook_id')::bigint = v_wid);

    -- KHUNG GIỜ GỬI (giờ VN): ngoài khung → bỏ qua, chỉ log skipped_window (không gửi bù)
    IF v_win_start IS NOT NULL AND v_win_end IS NOT NULL THEN
      v_local := now() AT TIME ZONE 'Asia/Ho_Chi_Minh';
      IF (v_win_dow IS NOT NULL AND NOT (EXTRACT(isodow FROM v_local)::smallint = ANY(v_win_dow)))
         OR v_local::time < v_win_start OR v_local::time > v_win_end THEN
        INSERT INTO public.aka_answer_quality_alert(gom_id,account_id,intent_code,answer_org_staff_id,answer_staff_name,
          reasons,relevance_score,attitude_state_code,alert_webhook_id,webhook_url,payload,net_request_id,status)
        VALUES (NEW.id,NEW.account_id,NEW.bot_intent,v_staff_id,v_staff,
          v_sub,NEW.relevance_score,NEW.attitude_state_code,v_wid,v_link,NULL,NULL,'skipped_window')
        ON CONFLICT (gom_id, alert_webhook_id) DO NOTHING;
        CONTINUE;
      END IF;
    END IF;

    IF v_cap IS NOT NULL AND v_staff_id IS NOT NULL THEN
      SELECT count(*) INTO v_cnt FROM public.aka_answer_quality_alert a
       WHERE a.answer_org_staff_id = v_staff_id
         AND a.alert_webhook_id = v_wid
         AND a.status IN ('sent','dry_run')
         AND (a.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
             = (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
      IF v_cnt >= v_cap THEN CONTINUE; END IF;
    END IF;

    v_summary := (SELECT string_agg(
        CASE WHEN b->>'type' = 'quality'
             THEN (b->>'name') || ' ' || (b->>'value') || '/' || (b->>'threshold')
             WHEN b->>'type' = 'cta'
             THEN 'CTA lỗi: ' || (b->>'name') || ' (điểm ' || COALESCE(b->>'value','?') || '/20'
                  || CASE WHEN COALESCE(NEW.cta_review->>'giai_doan','') <> ''
                          THEN ', giai đoạn ' || (NEW.cta_review->>'giai_doan') ELSE '' END || ')'
             ELSE 'Thái độ: ' || (b->>'name') || ' (' || (b->>'confidence') || ')' END, '; ')
      FROM jsonb_array_elements(v_sub) b);

    SELECT b->>'name' INTO v_cta_name FROM jsonb_array_elements(v_sub) b WHERE b->>'type'='cta' LIMIT 1;

    v_payload := jsonb_build_object(
      'alertReason',      CASE WHEN v_cta_name IS NOT NULL THEN 'CTA lỗi: ' || v_cta_name
                               ELSE 'Chất lượng/thái độ dưới ngưỡng' END,
      'staffName',        v_staff,
      'assignedVia',      v_res.o_via,
      'intent',           NEW.bot_intent || COALESCE(' - ' || v_intent.intent_name, ''),
      'customerName',     COALESCE(NEW.contact_name, ''),
      'customerQuestion', COALESCE(NEW.question_content, ''),
      'answerContent',    COALESCE(NEW.answer_content, ''),
      'relevanceScore',   NEW.relevance_score,
      'attitudeState',    COALESCE(NEW.attitude_state_code, ''),
      'attitudeEvidence', COALESCE(NEW.attitude_evidence, ''),
      'analysis',         COALESCE(NEW.relevance_analysis, ''),
      'suggestedReply',   COALESCE(NEW.relevance_suggested_reply, ''),
      'ctaRequired',      COALESCE(NEW.cta_review->>'can_thiet', ''),
      'ctaIssueCode',     COALESCE(NEW.cta_review->>'loi', ''),
      'ctaIssueLabel',    CASE NEW.cta_review->>'loi'
                            WHEN 'thieu' THEN 'Thiếu CTA'
                            WHEN 'yeu' THEN 'CTA yếu'
                            WHEN 'sai_giai_doan' THEN 'CTA sai giai đoạn'
                            WHEN 'lech_chu_de' THEN 'CTA lệch chủ đề'
                            WHEN 'ok' THEN 'CTA đạt'
                            WHEN 'khong_can' THEN 'Không cần CTA'
                            ELSE '' END,
      'ctaFound',         COALESCE(NEW.cta_review->>'hien_co', ''),
      'ctaNote',          COALESCE(NEW.cta_review->>'nhan_xet', ''),
      'ctaSuggested',     COALESCE(NEW.cta_review->>'de_xuat', ''),
      'ctaScore',         COALESCE(NEW.relevance_breakdown->>'cta_conversion', ''),
      'funnelStage',      COALESCE(NEW.cta_review->>'giai_doan', ''),
      'breachSummary',    COALESCE(v_summary, ''),
      'breaches',         v_sub,
      'pancakeLink',      v_pancake,
      'pancake_page',     COALESCE(v_shop, ''),
      'note',             CASE v_res.o_via
                            WHEN 'unassigned' THEN 'Contact chưa được gán NV quản lý'
                            WHEN 'page_manager' THEN 'Gửi tới NV quản lý page'
                            ELSE '' END
    );

    IF v_is_live THEN
      SELECT net.http_post(url := v_link, body := v_payload,
        headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req;
      INSERT INTO public.aka_answer_quality_alert(gom_id,account_id,intent_code,answer_org_staff_id,answer_staff_name,
        reasons,relevance_score,attitude_state_code,alert_webhook_id,webhook_url,payload,net_request_id,status)
      VALUES (NEW.id,NEW.account_id,NEW.bot_intent,v_staff_id,v_staff,
        v_sub,NEW.relevance_score,NEW.attitude_state_code,v_wid,v_link,v_payload,v_req,'sent')
      ON CONFLICT (gom_id, alert_webhook_id) DO NOTHING;
    ELSE
      INSERT INTO public.aka_answer_quality_alert(gom_id,account_id,intent_code,answer_org_staff_id,answer_staff_name,
        reasons,relevance_score,attitude_state_code,alert_webhook_id,webhook_url,payload,net_request_id,status)
      VALUES (NEW.id,NEW.account_id,NEW.bot_intent,v_staff_id,v_staff,
        v_sub,NEW.relevance_score,NEW.attitude_state_code,v_wid,v_link,v_payload,NULL,'dry_run')
      ON CONFLICT (gom_id, alert_webhook_id) DO NOTHING;
    END IF;
  END LOOP;

  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_notify_answer_quality error gom=% : %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notify_sales_unanswered()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_intent   public.aka_ai_intent%ROWTYPE;
  v_webhook  text;
  v_shop     text;
  v_page_id  text;
  v_link     text;
  v_staff    text;
  v_res      record;
  v_payload  jsonb;
  v_req_id   bigint;
BEGIN
  SELECT * INTO v_intent FROM public.aka_ai_intent
  WHERE intent_code = NEW.bot_intent AND is_active LIMIT 1;

  IF NOT FOUND OR COALESCE(v_intent.notify_staff, false) = false
     OR v_intent.notify_webhook_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT link INTO v_webhook FROM public.aka_webhook_link
  WHERE id = v_intent.notify_webhook_id;
  IF v_webhook IS NULL OR v_webhook = '' THEN RETURN NULL; END IF;

  IF EXISTS (SELECT 1 FROM public.aka_sales_alert_log WHERE gom_id = NEW.id) THEN
    RETURN NULL;
  END IF;

  SELECT name, pancake_page_id INTO v_shop, v_page_id
  FROM public.shops WHERE id = NEW.shop_id_2;

  v_link := CASE
    WHEN v_page_id IS NOT NULL AND NEW.conversation_id IS NOT NULL
    THEN 'https://pancake.vn/' || v_page_id || '?c_id=' || NEW.conversation_id
    ELSE '' END;

  SELECT * INTO v_res FROM public.fn_resolve_gom_staff(NEW.answer_org_staff_id, NEW.staff_id, NEW.contact_id, NEW.shop_id_2);

  IF v_res.o_org_staff_id IS NOT NULL THEN
    SELECT COALESCE(os.name_akabiz, os.name) INTO v_staff
    FROM public.org_staff os WHERE os.id = v_res.o_org_staff_id LIMIT 1;
  END IF;
  IF v_staff IS NULL OR v_staff = '' THEN v_staff := NULLIF(NEW.staff_name, ''); END IF;
  IF v_staff IS NULL OR v_staff = '' THEN v_staff := 'Chưa gán NV'; END IF;

  v_payload := jsonb_build_object(
    'staffName',        v_staff,
    'assignedVia',      v_res.o_via,
    'customerQuestion', COALESCE(NEW.question_content, ''),
    'questionMeaning',  v_intent.intent_name,
    'intent',           NEW.bot_intent || COALESCE(' - ' || v_intent.intent_name, ''),
    'customerName',     COALESCE(NEW.contact_name, ''),
    'pancakeLink',      v_link,
    'pancake_page',     COALESCE(v_shop, ''),
    'note',             CASE v_res.o_via
                          WHEN 'unassigned' THEN 'Contact chưa được gán NV quản lý'
                          WHEN 'page_manager' THEN 'Gửi tới NV quản lý page'
                          ELSE '' END
  );

  SELECT net.http_post(url := v_webhook, body := v_payload,
    headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req_id;

  INSERT INTO public.aka_sales_alert_log(gom_id, intent_code, webhook_url, payload, net_request_id)
  VALUES (NEW.id, NEW.bot_intent, v_webhook, v_payload, v_req_id)
  ON CONFLICT (gom_id) DO NOTHING;

  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_notify_sales_unanswered error gom=% : %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_opp_ctx(p_opp aka_salesopportunity)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare t record; cu record; st record; v_ctx jsonb; v_pc jsonb; v_seg text; v_state text; v_ren jsonb; v_trial date; v_ref text; v_ok bigint := 0; v_camp bigint := 0; cfg jsonb;
begin
  select * into t from public.aka_salesopportunity_type where id = p_opp.type_id;
  select name, phone, email, referrer_id, inbox_url, linh_vuc into cu from public.aka_customer where id = p_opp.customer_id;
  select name, phone into st from public.org_staff where id = p_opp.owner_org_staff_id;
  cfg := public.fn_opp_config();
  v_pc := public.fn_opp_product_context(p_opp.customer_id);
  v_trial := coalesce(p_opp.trial_start_date, public.fn_opp_trial_start(p_opp.customer_id));
  v_state := public.fn_opp_trial_state(p_opp.customer_id);
  if cu.referrer_id is not null then select name into v_ref from public.aka_customer where id = cu.referrer_id; end if;
  if t.anchor_kind = 'expiration' then
    v_ren := public.fn_opp_renewal_score(p_opp.customer_id, p_opp.anchor_date);
    v_seg := v_ren->>'group';
  elsif t.code = 'new_crm_data' then v_seg := public.fn_opp_lead_grade(p_opp.customer_id);
  elsif t.code = 'new_zalo' then
    select coalesce(c.gen_meta->>'ai_tier', c.gen_meta->>'tier') into v_seg from public.aka_crm c where c.id = p_opp.source_crm_id;
    v_seg := coalesce(v_seg, 'TRIAL');
  end if;
  -- số liệu bản thử / chiến dịch (hệ mới + cũ)
  select coalesce(sum(cnt),0), coalesce(sum(camps),0) into v_ok, v_camp from (
    select count(*) filter (where (d.report_group='success' OR (d.report_group IS NULL AND d.status in ('thành công','đã xem','đã tham gia')))) cnt, count(distinct c.id) camps
      from public.auto_campaigns c join public.org_organization g on g.id=c.organization_id
      left join public.auto_campaign_details d on d.campaign_id=c.id
     where g.customer_id=p_opp.customer_id and coalesce(c.is_delete,false)=false
    union all
    select coalesce(sum(tr.status_thanh_cong),0), count(distinct tr.campaign_id)
      from public.aka_order o join public.aka_tracking_app tr on tr.account_id=o.account_id_old
     where o.customer_id=p_opp.customer_id and tr.event_timestamp >= now()-interval '60 days') x;
  v_ctx := jsonb_build_object(
    'today', public.fn_opp_today_vn(), 'trial_start', v_trial, 'state', v_state, 'segment', v_seg,
    'product_group', v_pc->>'product_group', 'package', v_pc->>'package', 'renewal', v_ren,
    'h_date', case when t.anchor_kind='expiration' then p_opp.anchor_date end,
    'has_phone', nullif(cu.phone,'') is not null, 'has_email', nullif(cu.email,'') is not null,
    'ten', coalesce(cu.name,'anh/chị'), 'san_pham', coalesce(nullif(v_pc->>'product_raw',''),'akaBiz'),
    'goi', v_pc->>'package', 'ngay_het_han', case when t.anchor_kind='expiration' then to_char(p_opp.anchor_date,'DD/MM/YYYY') end,
    'so_ngay_con', case when t.anchor_kind='expiration' then (p_opp.anchor_date - public.fn_opp_today_vn())::text end,
    'nv_ten', coalesce(st.name,''), 'nv_sdt', coalesce(st.phone,''), 'nguoi_gioi_thieu', coalesce(v_ref,''),
    'so_tin_thanh_cong', v_ok::text, 'so_chien_dich', v_camp::text, 'nganh', coalesce(cu.linh_vuc,'{nganh}'), 'inbox_url', cu.inbox_url)
    || coalesce(cfg->'placeholders', '{}'::jsonb);
  return v_ctx;
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_sinh_buoc(p_opp_id bigint, p_ngay date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.aka_salesopportunity; t record; cfg jsonb; ctx jsonb; steps jsonb; s jsonb; v_ngay date; v_off_anchor int; v_off_trial int;
        v_from text; v_code text; v_actor text; v_actions jsonb; v_created int := 0; v_progress jsonb; v_trial date;
        v_replied48 boolean; v_due timestamptz; v_due_date date; v_due_time text; v_chan bigint; v_content text; v_note text; v_crm_id bigint;
        v_staff_ok boolean; v_auto_ok boolean; v_manual boolean; v_prio int; cu record; a text; v_next jsonb; v_min_off int := null; v_auto_send boolean;
        v_gen_status text; v_dow int; v_has_call boolean; v_has_zalo boolean;
begin
  select * into o from public.aka_salesopportunity where id = p_opp_id for update;
  if not found or o.status <> 'open' then return 0; end if;
  select * into t from public.aka_salesopportunity_type where id = o.type_id;
  cfg := public.fn_opp_config();
  v_auto_send := coalesce((cfg->>'auto_send_enabled')::boolean, false);
  v_ngay := coalesce(p_ngay, public.fn_opp_today_vn());
  -- luật dừng: CSDL thấy khách đang trả phí với cơ hội bán mới → won
  if t.opportunity_type = 'new_sale' and t.auto_close_on_purchase and public.fn_trang_thai_mua(o.customer_id) = 'dang_dung' then
    perform public.fn_dong_co_hoi_ban_hang(o.id, 'won', 'purchased_detected');
    return 0;
  end if;
  ctx := public.fn_opp_ctx(o);
  if not coalesce((cfg->>'step_generation_enabled')::boolean, true) then
    -- tạm dừng sinh task: vẫn cập nhật ngày thử để vòng đời đúng, không insert aka_crm
    if (ctx->>'trial_start') is not null and o.trial_start_date is distinct from (ctx->>'trial_start')::date then
      update public.aka_salesopportunity set trial_start_date = (ctx->>'trial_start')::date where id = o.id;
    end if;
    return 0;
  end if;
  v_trial := (ctx->>'trial_start')::date;
  if v_trial is not null and o.trial_start_date is distinct from v_trial then
    update public.aka_salesopportunity set trial_start_date = v_trial where id = o.id;  -- trigger BEFORE UPDATE kéo dài lifecycle
  end if;
  select * into cu from public.aka_customer where id = o.customer_id;
  v_progress := coalesce(o.care_progress, '{}'::jsonb);
  v_off_anchor := v_ngay - o.anchor_date;
  v_off_trial := case when v_trial is not null then v_ngay - v_trial end;
  v_replied48 := not public.fn_opp_cond('silent_48h', o, ctx);
  v_dow := extract(dow from v_ngay)::int;  -- 0 = CN, 6 = T7
  steps := public.fn_opp_steps(o.type_id);

  for s in select * from jsonb_array_elements(steps) loop
    v_code := s->>'code'; v_from := coalesce(s->>'from','anchor');
    if v_progress ? v_code then continue; end if;
    if v_from = 'trial_start' then
      if v_off_trial is null then continue; end if;
      if (s->>'offset')::int <> v_off_trial then
        if (s->>'offset')::int > v_off_trial then v_min_off := least(coalesce(v_min_off, 9999), (s->>'offset')::int - v_off_trial); end if;
        continue;
      end if;
    else
      if (s->>'offset')::int <> v_off_anchor then
        if (s->>'offset')::int > v_off_anchor then v_min_off := least(coalesce(v_min_off, 9999), (s->>'offset')::int - v_off_anchor); end if;
        continue;
      end if;
    end if;

    s := public.fn_opp_apply_variants(s, ctx);
    if coalesce((s->>'skip')::boolean,false) then v_progress := v_progress || jsonb_build_object(v_code, 'skipped:'||coalesce(s->>'skip_reason','variant')); continue; end if;
    if public.fn_opp_conds_any(s->'skip_if', o, ctx) then v_progress := v_progress || jsonb_build_object(v_code, 'skipped:skip_if'); continue; end if;
    if s ? 'only_if' and jsonb_array_length(coalesce(s->'only_if','[]'::jsonb)) > 0 and not public.fn_opp_conds_all(s->'only_if', o, ctx) then
      v_progress := v_progress || jsonb_build_object(v_code, 'skipped:only_if'); continue; end if;

    v_actor := coalesce(s->>'actor','staff'); v_actions := coalesce(s->'actions','["zalo"]'::jsonb);
    v_manual := false;
    if v_actor = 'auto' and v_replied48 then v_actor := 'staff'; v_manual := true; end if;      -- T-reply: khách vừa nhắn → NV gửi tay
    if v_actor = 'auto' and not v_auto_send then v_actor := 'staff'; v_manual := true; end if;  -- worker gửi chưa bật → NV gửi tay
    v_staff_ok := v_actor in ('staff','both') and (v_actor <> 'both' or public.fn_opp_conds_all(s->'only_if_staff', o, ctx));
    v_auto_ok  := v_actor in ('auto','both') and (v_actor <> 'both' or public.fn_opp_conds_all(s->'only_if_auto', o, ctx));
    if v_actor = 'both' and v_auto_ok and (v_replied48 or not v_auto_send) then v_auto_ok := false; if not v_staff_ok then v_staff_ok := true; v_manual := true; end if; end if;
    if not v_staff_ok and not v_auto_ok then v_progress := v_progress || jsonb_build_object(v_code, 'skipped:only_if_staff'); continue; end if;

    -- giờ hẹn (CN → T2; T7 chỉ NV)
    v_due_time := coalesce(s->>'due_time_vn', cfg->'global_rules'->>'due_time_default_vn', '08:30');
    v_due_date := v_ngay;
    if v_dow = 0 then v_due_date := v_ngay + 1; elsif v_dow = 6 and v_actor = 'auto' then v_due_date := v_ngay + 2; end if;
    if v_due_time = 'immediate' then v_due := now();
    else v_due := (v_due_date::text || ' ' || v_due_time)::timestamp at time zone 'Asia/Ho_Chi_Minh'; end if;
    v_prio := coalesce((s->>'priority')::int, 20) + coalesce((t.care_process->>'priority_boost')::int, 0);

    v_has_call := v_actions ? 'call'; v_has_zalo := v_actions ? 'zalo';
    -- task NV: gộp call+zalo
    if v_staff_ok and (v_has_call or v_has_zalo or v_actor = 'staff') then
      v_chan := case when v_has_call then 10 else 8 end;
      v_content := public.fn_opp_render(coalesce(s->'content'->>'zalo', s->'content'->>'call', s->'content'->>'sms'), ctx);
      v_note := format('[Cơ hội #%s · %s · %s%s] %s', o.id, t.name, v_code, case when v_manual then ' · AUTO→NV gửi tay' else '' end, coalesce(s->>'goal',''));
      v_gen_status := 'scheduled';
      insert into public.aka_crm (customer_id, customer_name, customer_phone, crm_type_id, priority, org_staff_owner_id, organization_id, created_by,
              cskh_due_date, note, task_note, pancake_url, suggested_channel_id, suggested_content, is_read, source_type, gen_status, gen_agent, gen_at, gen_meta,
              sales_opportunity_id, interest_product_ids, source_expiration_date)
      values (o.customer_id, cu.name, cu.phone, t.crm_type_id, v_prio, o.owner_org_staff_id, o.organization_id, o.owner_org_staff_id,
              v_due, left(v_note, 500), left(public.fn_opp_render(coalesce(s->'content'->>'call',''), ctx), 1000), cu.inbox_url, v_chan, v_content, false, 'sales_opp', v_gen_status, 'sales_opp_v2', now(),
              jsonb_build_object('opp_id', o.id, 'type_code', t.code, 'step_code', v_code, 'from', v_from, 'offset', s->>'offset', 'actor', 'staff', 'manual_send', v_manual,
                                 'actions', v_actions, 'segment', ctx->>'segment', 'state', ctx->>'state', 'variant_applied', s->'variant_applied', 'why', s->>'why'),
              o.id, case when o.product_id is not null then array[o.product_id] end, case when t.anchor_kind='expiration' then o.anchor_date end)
      on conflict do nothing
      returning id into v_crm_id;
      if v_crm_id is not null then v_created := v_created + 1; v_progress := v_progress || jsonb_build_object(v_code, v_crm_id); end if;
    end if;
    -- task auto: từng kênh
    if v_auto_ok then
      for a in select value #>> '{}' from jsonb_array_elements(v_actions) loop
        if a not in ('zalo','email','sms') then continue; end if;
        if a = 'zalo' and v_staff_ok then continue; end if;   -- NV đã nhận phần Zalo
        if a = 'email' and not coalesce((ctx->>'has_email')::boolean,false) then continue; end if;
        v_chan := case a when 'zalo' then 8 when 'email' then 121 else 9 end;
        v_content := public.fn_opp_render(case a when 'email' then coalesce(s->'content'->'email'->>'subject','')||E'\n'||coalesce(s->'content'->'email'->>'body','') else s->'content'->>a end, ctx);
        if v_content is null or v_content = '' then continue; end if;
        insert into public.aka_crm (customer_id, customer_name, customer_phone, crm_type_id, priority, org_staff_owner_id, organization_id, created_by,
                cskh_due_date, note, pancake_url, suggested_channel_id, suggested_content, is_read, source_type, gen_status, gen_agent, gen_at, gen_meta,
                sales_opportunity_id, interest_product_ids, source_expiration_date)
        values (o.customer_id, cu.name, cu.phone, t.crm_type_id, v_prio + 10, o.owner_org_staff_id, o.organization_id, o.owner_org_staff_id,
                v_due, left(format('[Cơ hội #%s · %s · %s · AUTO %s] %s', o.id, t.name, v_code, a, coalesce(s->>'goal','')), 500), cu.inbox_url, v_chan, v_content, false, 'sales_opp', 'pending_send', 'sales_opp_v2', now(),
                jsonb_build_object('opp_id', o.id, 'type_code', t.code, 'step_code', v_code, 'from', v_from, 'offset', s->>'offset', 'actor', 'auto', 'channel', a,
                                   'segment', ctx->>'segment', 'state', ctx->>'state', 'variant_applied', s->'variant_applied'),
                o.id, case when o.product_id is not null then array[o.product_id] end, case when t.anchor_kind='expiration' then o.anchor_date end)
        on conflict do nothing
        returning id into v_crm_id;
        if v_crm_id is not null then v_created := v_created + 1; v_progress := v_progress || jsonb_build_object(v_code || ':' || a, v_crm_id); if not (v_progress ? v_code) then v_progress := v_progress || jsonb_build_object(v_code, v_crm_id); end if; end if;
      end loop;
    end if;
  end loop;

  update public.aka_salesopportunity
     set care_progress = v_progress,
         next_action_at = case when v_min_off is not null then ((v_ngay + v_min_off)::text || ' 08:30')::timestamp at time zone 'Asia/Ho_Chi_Minh' else next_action_at end,
         next_action_type = coalesce(next_action_type, 'follow_up'),
         version = version + 1
   where id = o.id;
  return v_created;
end $function$

CREATE OR REPLACE FUNCTION public.fn_resolve_gom_staff(p_answer_org_staff_id bigint, p_staff_id uuid, p_contact_id uuid, p_shop_id uuid, OUT o_org_staff_id bigint, OUT o_via text)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_answer_org_staff_id IS NOT NULL THEN
    o_org_staff_id := p_answer_org_staff_id; o_via := 'direct'; RETURN;
  END IF;

  IF p_staff_id IS NOT NULL THEN
    SELECT os.id INTO o_org_staff_id FROM org_staff os
    WHERE os.chat_staff_id = p_staff_id LIMIT 1;
    IF o_org_staff_id IS NOT NULL THEN o_via := 'mapped'; RETURN; END IF;
  END IF;

  IF p_contact_id IS NOT NULL THEN
    BEGIN
      SELECT os.id INTO o_org_staff_id
      FROM contacts c
      JOIN org_staff os ON os.chat_staff_id = NULLIF((c.staff_ids)[1],'')::uuid AND os.is_active
      WHERE c.id = p_contact_id LIMIT 1;
    EXCEPTION WHEN OTHERS THEN o_org_staff_id := NULL;
    END;
    IF o_org_staff_id IS NOT NULL THEN o_via := 'contact_owner'; RETURN; END IF;

    SELECT ac.org_staff_id_owner INTO o_org_staff_id
    FROM contacts c JOIN aka_customer ac ON ac.id = c.customer_id
    WHERE c.id = p_contact_id AND ac.org_staff_id_owner IS NOT NULL LIMIT 1;
    IF o_org_staff_id IS NOT NULL THEN o_via := 'customer_owner'; RETURN; END IF;
  END IF;

  -- Tầng 5: NV quản lý chính của page Pancake
  IF p_shop_id IS NOT NULL THEN
    SELECT s.manager_org_staff_id INTO o_org_staff_id
    FROM shops s WHERE s.id = p_shop_id AND s.manager_org_staff_id IS NOT NULL;
    IF o_org_staff_id IS NOT NULL THEN o_via := 'page_manager'; RETURN; END IF;
  END IF;

  o_via := 'unassigned';
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tao_co_hoi_ban_hang(p_customer_id bigint, p_type_id bigint DEFAULT NULL::bigint, p_source_kind text DEFAULT 'crm'::text, p_source_crm_id bigint DEFAULT NULL::bigint, p_owner_staff_id bigint DEFAULT NULL::bigint, p_anchor_date date DEFAULT NULL::date, p_product_id bigint DEFAULT NULL::bigint, p_created_by bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_force boolean DEFAULT false)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id bigint; t record; v_anchor date; v_org bigint; v_owner bigint; cfg jsonb; v_live boolean; c record; cu record; v_key text; v_try int := 0; v_progress jsonb := '{}'::jsonb; s jsonb;
begin
  if p_customer_id is null then return null; end if;
  perform pg_advisory_xact_lock(hashtext('sales_opp:' || p_customer_id));

  select id into v_id from public.aka_salesopportunity where customer_id = p_customer_id and status = 'open' limit 1;
  if v_id is not null then
    if p_source_crm_id is not null then
      update public.aka_crm set sales_opportunity_id = v_id where id = p_source_crm_id and sales_opportunity_id is null;
      perform public.fn_opp_ghi_tin_hieu(v_id, p_source_crm_id);
    end if;
    return v_id;
  end if;

  select * into t from public.aka_salesopportunity_type
   where id = coalesce(p_type_id, public.fn_opp_suy_loai(p_customer_id, p_source_crm_id)) and is_active;
  if t.id is null then perform public.fn_opp_log('partial', format('không suy được loại cho khách %s', p_customer_id)); return null; end if;

  cfg := public.fn_opp_config();
  v_live := p_force or (cfg->>'mode' = 'live' and (cfg->'live_types') ? t.code);

  select * into c from public.aka_crm where id = p_source_crm_id;
  select * into cu from public.aka_customer where id = p_customer_id;

  if t.anchor_kind = 'expiration' then
    v_anchor := coalesce(p_anchor_date, c.source_expiration_date, public.fn_opp_ngay_het_han(p_customer_id));
    if v_anchor is null then perform public.fn_opp_log('partial', format('loại %s cần ngày hết hạn, khách %s', t.code, p_customer_id)); return null; end if;
    if public.fn_opp_today_vn() > v_anchor + coalesce(t.window_after_days,30) then v_anchor := public.fn_opp_today_vn() - coalesce(t.window_after_days,30); end if;
  else
    v_anchor := coalesce(p_anchor_date, public.fn_opp_today_vn());
  end if;

  v_owner := coalesce(p_owner_staff_id, c.org_staff_owner_id, cu.org_staff_id_owner, c.created_by);
  if v_owner is null then perform public.fn_opp_log('partial', format('không có NV phụ trách cho khách %s (crm %s)', p_customer_id, p_source_crm_id)); return null; end if;
  v_org := coalesce(c.organization_id, 1);

  if not v_live then
    perform public.fn_opp_log('success', format('DRY-RUN: sẽ tạo cơ hội %s cho khách %s (crm %s, neo %s)', t.code, p_customer_id, p_source_crm_id, v_anchor),
      jsonb_build_object('dry_run', true, 'type_code', t.code, 'customer_id', p_customer_id, 'source_crm_id', p_source_crm_id, 'anchor', v_anchor, 'owner', v_owner));
    return null;
  end if;

  -- bước offset 0 tính từ mốc gốc đã được task nguồn bao phủ
  if p_source_crm_id is not null then
    for s in select * from jsonb_array_elements(public.fn_opp_steps(t.id)) loop
      if coalesce(s->>'from','anchor') = 'anchor' and (s->>'offset')::int = 0 then v_progress := v_progress || jsonb_build_object(s->>'code', p_source_crm_id); end if;
    end loop;
  end if;

  v_key := format('opp:%s:%s:%s', p_customer_id, t.code, v_anchor);
  loop
    begin
      insert into public.aka_salesopportunity
        (title, organization_id, customer_id, owner_org_staff_id, type_id, anchor_date, lifecycle_end_at, trial_start_date,
         source_kind, source_crm_id, product_id, created_by_org_staff_id, next_action_note, idempotency_key, opportunity_type, stage, care_progress)
      values
        ('', v_org, p_customer_id, v_owner, t.id, v_anchor, now(), public.fn_opp_trial_start(p_customer_id),
         coalesce(p_source_kind,'crm'), p_source_crm_id, p_product_id, coalesce(p_created_by, v_owner), p_note, v_key, t.opportunity_type, t.default_stage, v_progress)
      returning id into v_id;
      exit;
    exception when unique_violation then
      v_try := v_try + 1;
      if v_try > 5 then raise; end if;
      v_key := format('opp:%s:%s:%s:r%s', p_customer_id, t.code, v_anchor, v_try);
    end;
  end loop;

  if p_source_crm_id is not null then
    update public.aka_crm set sales_opportunity_id = v_id where id = p_source_crm_id;
    perform public.fn_opp_ghi_tin_hieu(v_id, p_source_crm_id);
  end if;
  perform public.fn_opp_sinh_buoc(v_id, public.fn_opp_today_vn());
  perform public.fn_opp_log('success', format('Tạo cơ hội #%s %s cho khách %s (crm %s)', v_id, t.code, p_customer_id, p_source_crm_id),
    jsonb_build_object('opp_id', v_id, 'type_code', t.code, 'customer_id', p_customer_id, 'source_crm_id', p_source_crm_id), 1);
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.fn_weekly_staff_digest()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_week_start date := (date_trunc('week', now() AT TIME ZONE 'Asia/Ho_Chi_Minh'))::date;
  v_from timestamptz := (v_week_start - 7)::timestamptz;
  v_to   timestamptz := v_week_start::timestamptz;
  v_link text; v_is_live boolean;
  s record; v_case record; v_weak record;
  v_praise text; v_improve text;
  v_payload jsonb; v_req bigint; v_sent integer := 0;
BEGIN
  SELECT link, is_live INTO v_link, v_is_live FROM aka_webhook_link WHERE id = 5;
  IF v_link IS NULL OR v_link = '' THEN RETURN 0; END IF;

  FOR s IN
    SELECT nhan_vien_id, max(nhan_vien_ten) ten, count(*) n_msg,
           round(avg(tong_diem),1) avg_msg,
           round(100.0*count(*) FILTER (WHERE trang_thai_thai_do IN ('than_thien_dong_cam','nhiet_tinh_chu_dong'))/count(*),0) pos_pct,
           round(100.0*count(*) FILTER (WHERE trang_thai_thai_do IN ('tho_o_phot_lo','coc_loc_qua_ngan','thieu_kien_nhan','gat_gong_phong_thu'))/count(*),0) neg_pct
    FROM aka_chat_answer_evaluation
    WHERE is_akabiz AND nhan_vien_id IS NOT NULL AND tong_diem IS NOT NULL
      AND cham_luc >= v_from AND cham_luc < v_to
    GROUP BY nhan_vien_id
    HAVING count(*) >= 5
  LOOP
    IF EXISTS (SELECT 1 FROM aka_staff_digest_log WHERE org_staff_id = s.nhan_vien_id AND week_start = v_week_start) THEN CONTINUE; END IF;

    SELECT count(*) n_case, round(avg(tong_diem_chat_luong),1) avg_case, round(avg(diem_thai_do),1) avg_att
    INTO v_case
    FROM aka_chat_support_evaluation
    WHERE is_akabiz AND org_staff_id = s.nhan_vien_id AND ngay_danh_gia >= v_week_start - 7 AND ngay_danh_gia < v_week_start;

    SELECT name, pct INTO v_weak FROM (
      SELECT unnest(ARRAY['Chính xác','Đầy đủ','Cá nhân hóa','Phong cách','Xử lý','Thái độ','Kêu gọi hành động']) name,
             unnest(ARRAY[
               round(avg(q_chinh_xac)/25*100,0), round(avg(q_day_du)/15*100,0), round(avg(q_ca_nhan_hoa)/10*100,0),
               round(avg(q_phong_cach)/10*100,0), round(avg(q_xu_ly)/10*100,0), round(avg(q_thai_do)/10*100,0),
               round(avg(q_keu_goi_hanh_dong)/20*100,0)]) pct
      FROM aka_chat_answer_evaluation
      WHERE is_akabiz AND nhan_vien_id = s.nhan_vien_id AND cham_luc >= v_from AND cham_luc < v_to
    ) t WHERE pct IS NOT NULL ORDER BY pct ASC LIMIT 1;

    SELECT string_agg('⭐ ' || tong_diem || 'đ | KH: ' || left(coalesce(cau_hoi,''),120) || E'\n→ ' || left(coalesce(cau_tra_loi,''),200), E'\n\n' ORDER BY tong_diem DESC)
    INTO v_praise
    FROM (SELECT tong_diem, cau_hoi, cau_tra_loi FROM aka_chat_answer_evaluation
          WHERE is_akabiz AND nhan_vien_id = s.nhan_vien_id AND cham_luc >= v_from AND cham_luc < v_to AND tong_diem >= 75
          ORDER BY tong_diem DESC LIMIT 2) q;

    SELECT string_agg('⚠️ ' || tong_diem || 'đ | KH: ' || left(coalesce(cau_hoi,''),120) || E'\n→ Đã trả lời: ' || left(coalesce(cau_tra_loi,''),150)
           || CASE WHEN cau_tra_loi_de_xuat IS NOT NULL AND cau_tra_loi_de_xuat <> '' THEN E'\n✅ Nên trả lời: ' || left(cau_tra_loi_de_xuat,250) ELSE '' END, E'\n\n' ORDER BY tong_diem ASC)
    INTO v_improve
    FROM (SELECT tong_diem, cau_hoi, cau_tra_loi, cau_tra_loi_de_xuat FROM aka_chat_answer_evaluation
          WHERE is_akabiz AND nhan_vien_id = s.nhan_vien_id AND cham_luc >= v_from AND cham_luc < v_to AND tong_diem < 60
          ORDER BY tong_diem ASC LIMIT 2) q;

    v_payload := jsonb_build_object(
      'digestType',   'weekly_staff',
      'staffName',    coalesce(s.ten,'?'),
      'weekRange',    to_char(v_week_start - 7,'DD/MM') || ' - ' || to_char(v_week_start - 1,'DD/MM/YYYY'),
      'msgCount',     s.n_msg,
      'avgMsgScore',  s.avg_msg,
      'caseCount',    coalesce(v_case.n_case,0),
      'avgCaseScore', v_case.avg_case,
      'avgCaseAttitude', v_case.avg_att,
      'attitudePosPct', s.pos_pct,
      'attitudeNegPct', s.neg_pct,
      'weakestCriterion', coalesce(v_weak.name,'') || CASE WHEN v_weak.pct IS NOT NULL THEN ' (' || v_weak.pct || '% điểm tối đa)' ELSE '' END,
      'praiseBlock',  coalesce(v_praise,'(tuần này chưa có câu ≥75đ — cùng cố gắng tuần sau nhé)'),
      'improveBlock', coalesce(v_improve,'(không có câu dưới 60đ — làm tốt lắm!)'),
      'note',         'Digest tuần tự động: điểm vụ việc là KPI chính; câu mẫu để tham khảo cách trả lời tốt hơn'
    );

    IF v_is_live THEN
      SELECT net.http_post(url := v_link, body := v_payload, headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req;
      INSERT INTO aka_staff_digest_log(org_staff_id, staff_name, week_start, payload, net_request_id, status)
      VALUES (s.nhan_vien_id, s.ten, v_week_start, v_payload, v_req, 'sent') ON CONFLICT DO NOTHING;
    ELSE
      INSERT INTO aka_staff_digest_log(org_staff_id, staff_name, week_start, payload, net_request_id, status)
      VALUES (s.nhan_vien_id, s.ten, v_week_start, v_payload, NULL, 'dry_run') ON CONFLICT DO NOTHING;
    END IF;
    v_sent := v_sent + 1;
  END LOOP;
  RETURN v_sent;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_staff_zalo_runtime_mode(p_staff_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_mode record;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Staff ID must be a positive integer';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id);

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Active staff % was not found', p_staff_id;
  END IF;

  SELECT * INTO v_mode
  FROM public.resolve_organization_zalo_runtime_mode(v_organization_id);

  RETURN jsonb_build_object(
    'staff_id', p_staff_id,
    'is_zalo_server', COALESCE(v_mode.is_zalo_server, false),
    'is_zalo_show_web', COALESCE(v_mode.web_enabled, false),
    'zalo_qr_enabled', COALESCE(v_mode.qr_enabled, false),
    'zalo_web_enabled', COALESCE(v_mode.web_enabled, false),
    'revision', COALESCE(v_mode.mode_revision, 'none:' || v_organization_id::text)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_legacy_zalo_account_server_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_legacy_is_zalo_server boolean := false;
BEGIN
  -- Explicit true/false is a new-client subtype decision. Only omitted/NULL
  -- values use the legacy v218 organization-wide owner.
  IF NEW.is_zalo_server IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF lower(btrim(COALESCE(NEW.flatform_type, ''))) <> 'zalo'
    OR COALESCE(NEW.is_zalo_show_web, false)
  THEN
    NEW.is_zalo_server := false;
    RETURN NEW;
  END IF;

  v_organization_id := NEW.organization_id;
  IF v_organization_id IS NULL AND NEW.staff_id IS NOT NULL THEN
    SELECT staff.organization_id
    INTO v_organization_id
    FROM public.org_staff AS staff
    WHERE staff.id = NEW.staff_id;
  END IF;

  IF v_organization_id IS NOT NULL THEN
    SELECT COALESCE(mode.is_zalo_server, false)
    INTO v_legacy_is_zalo_server
    FROM public.resolve_organization_zalo_runtime_mode(v_organization_id) AS mode;
  END IF;

  NEW.is_zalo_server := COALESCE(v_legacy_is_zalo_server, false);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_non_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_platform text, p_previous_status text, p_claim_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_platform text := lower(btrim(COALESCE(p_platform, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_platform NOT IN ('facebook', 'email') THEN
    RAISE EXCEPTION 'Non-Zalo runtime platform must be Facebook or Email';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN false; END IF;

  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = v_platform
  FOR UPDATE OF account;
  IF NOT FOUND THEN RETURN false; END IF;

  UPDATE public.auto_accounts AS account
  SET
    status = v_previous_status,
    runtime_operation_claim_token = NULL,
    updated_at = now()
  WHERE account.id = p_account_id
    AND account.status = 'đang chạy'
    AND account.runtime_operation_claim_token = p_claim_token;
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN false; END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE OF account;
  IF NOT FOUND THEN RETURN false; END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  -- Release is cleanup, not a new operation. Capability loss does not prevent
  -- either runtime from releasing its own subtype.
  IF (v_runtime_target = 'server' AND (v_is_web OR NOT v_is_server))
    OR (v_runtime_target = 'desktop' AND v_is_server)
  THEN RETURN false; END IF;

  UPDATE public.auto_accounts
  SET status = v_previous_status, updated_at = now()
  WHERE id = p_account_id AND status = 'đang chạy';
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text, p_claim_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN RAISE EXCEPTION 'Account and staff IDs must be positive integers'; END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
  FOR SHARE OF staff;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN false; END IF;

  UPDATE public.auto_accounts AS account
  SET
    status = v_previous_status,
    runtime_operation_claim_token = NULL,
    updated_at = now()
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND account.status = 'đang chạy'
    AND account.runtime_operation_claim_token = p_claim_token;
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_aka_crm_sales_opportunity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cfg jsonb; ct record; v_opp bigint; v_status_changed boolean; v_purchased boolean;
begin
  begin
    if new.customer_id is null or coalesce(new.source_type,'') = 'sales_opp' then return new; end if;
    cfg := public.fn_opp_config();
    if coalesce(cfg->>'mode','off') = 'off' then return new; end if;

    if tg_op = 'INSERT' then
      select auto_create_opportunity, opportunity_type_id into ct from public.aka_crm_type where id = new.crm_type_id;
      if coalesce(ct.auto_create_opportunity, false) then
        perform public.fn_tao_co_hoi_ban_hang(new.customer_id, ct.opportunity_type_id, 'crm', new.id, new.org_staff_owner_id, new.source_expiration_date, new.interest_product_ids[1], new.created_by);
      end if;
      return new;
    end if;

    -- UPDATE
    v_purchased := (new.purchase_date is not null and old.purchase_date is null) or (new.pipeline_status_id = 4 and old.pipeline_status_id is distinct from 4);
    if v_purchased and coalesce((cfg->>'sale_order_won_enabled')::boolean, true) then
      select id into v_opp from public.aka_salesopportunity where customer_id = new.customer_id and status = 'open' limit 1;
      if v_opp is not null then perform public.fn_dong_co_hoi_ban_hang(v_opp, 'won', 'crm_purchase', nullif(new.revenue,0), new.sale_order_id); end if;
      return new;
    end if;

    v_status_changed := (new.pipeline_status_id in (2,3,105) and new.pipeline_status_id is distinct from old.pipeline_status_id)
                     or (new.interest_date is not null and old.interest_date is null)
                     or (new.demo_date is not null and old.demo_date is null)
                     or (new.negotiation_date is not null and old.negotiation_date is null);
    if v_status_changed and coalesce((cfg->>'pipeline_trigger_enabled')::boolean, true) then
      perform public.fn_tao_co_hoi_ban_hang(new.customer_id, null, 'crm', new.id, new.org_staff_owner_id, new.source_expiration_date, coalesce(new.negotiation_product_ids[1], new.demo_product_ids[1], new.interest_product_ids[1]), new.org_staff_updated_id);
    end if;

    if coalesce((cfg->>'auto_close_lost_enabled')::boolean,false) and new.decline_reason_id in (21,30,31) and old.decline_reason_id is distinct from new.decline_reason_id then
      select id into v_opp from public.aka_salesopportunity where customer_id = new.customer_id and status = 'open' limit 1;
      if v_opp is not null then perform public.fn_dong_co_hoi_ban_hang(v_opp, 'lost', (select name from public.aka_crm_status where id = new.decline_reason_id)); end if;
    end if;
    if coalesce((cfg->>'auto_close_disqualified_enabled')::boolean,false) and new.error_reason_id in (16,17,56) and old.error_reason_id is distinct from new.error_reason_id then
      select id into v_opp from public.aka_salesopportunity where customer_id = new.customer_id and status = 'open' limit 1;
      if v_opp is not null then perform public.fn_dong_co_hoi_ban_hang(v_opp, 'disqualified', 'data_error'); end if;
    end if;
    return new;
  exception when others then
    perform public.fn_opp_log('failed', format('trigger aka_crm #%s: %s', new.id, left(sqlerrm, 300)), jsonb_build_object('crm_id', new.id, 'op', tg_op), 0, 0, 1);
    return new;
  end;
end $function$
